# Elements that commonly exhibit mixed valence in spinels
VARIABLE_VALENCE_ELEMENTS = {
    'Fe', 'Mn', 'Co', 'Cu', 'Cr', 'V', 'Ni', 'Ti', 'Ce', 'Eu', 'Ru', 'Rh', 'Ir'
}

# ============================================================================
# DATA INTEGRITY TIER SYSTEM (NEW IN v1.7)
# ============================================================================
# Classifies each site (and hence each structure) into one of three tiers
# based on the reliability of the oxidation state assignment and BVS result.
#
# ACCEPT: Valence assignment is unambiguous (integer formal states, or
#         single-element sites with charge-balance-determined non-integer states).
# FLAG:   Two or more TM elements share a crystallographic site AND at least one
#         has a non-integer assigned valence. The valence partitioning is an
#         assumption made by the depositor and cannot be verified from diffraction.
# EXPUNGE: BVS result is demonstrably meaningless (implausible coordinates or
#          minority species on a site dominated by a different cation).
#
# See: Eir 1.7 Specification (NRM, May 2026)
# ============================================================================

TRANSITION_METALS = {
    'Sc', 'Ti', 'V', 'Cr', 'Mn', 'Fe', 'Co', 'Ni', 'Cu', 'Zn',
    'Y', 'Zr', 'Nb', 'Mo', 'Tc', 'Ru', 'Rh', 'Pd', 'Ag', 'Cd',
    'Hf', 'Ta', 'W', 'Re', 'Os', 'Ir', 'Pt', 'Au', 'Hg',
    'La', 'Ce', 'Pr', 'Nd', 'Sm', 'Eu', 'Gd', 'Tb', 'Dy', 'Ho', 'Er', 'Tm', 'Yb', 'Lu',
}

# Thresholds for EXPUNGE tier
MINORITY_OCC_THRESHOLD = 0.05  # Occupancy below which a species is "minority"
MAJORITY_OCC_THRESHOLD = 0.90  # Occupancy above which another species dominates


def is_transition_metal(element):
    """Check if an element is a transition metal (d-block or lanthanide)."""
    return element in TRANSITION_METALS


# v2.0.2: 0.045, not 0.05.
#
# Fractional valences in the ICSD cluster on two decimal places, so a boundary
# at exactly 0.05 sits on a value depositors write. ICSD 215426-215430 is one
# compositional series from one 2013 study, Mn(1+x)Tb(1-x)O3, with Mn valences
# of 3.10, 3.08, 3.07, 3.06 and 3.05. The first four were tiered FLAG and the
# last ACCEPT, on chemistry that is identical across the series, purely because
# 3.05 lands on the threshold. abs(3.05 - 3) is 0.05000000000000071 in binary,
# so the comparison is decided by floating-point representation rather than by
# anything about the structure.
#
# Moving the boundary to 0.045 puts it between the values depositors use, and
# the comparison is now explicit about which side is which. Callers that need
# to see a borderline case should read valence_integer_distance rather than
# rely on the verdict alone.
VALENCE_INTEGER_TOL = 0.045


def valence_integer_distance(valence):
    """How far a valence sits from the nearest integer. None if unstated."""
    if valence is None:
        return None
    try:
        v = float(valence)
    except (TypeError, ValueError):
        return None
    if v != v:
        return None
    return abs(v - round(v))


def is_valence_integer(valence, tolerance=VALENCE_INTEGER_TOL):
    """
    Is a valence effectively integer?

    3.99 is clearly Mn(4+) rounded and counts as integer; 3.313 is a genuine
    charge-balance average and does not. See VALENCE_INTEGER_TOL for why the
    boundary is 0.045 rather than 0.05.
    """
    d = valence_integer_distance(valence)
    if d is None:
        return True  # No valence stated = no non-integer flag
    return d <= tolerance


# RETIRED at v2.0.11: assign_site_integrity_tier, assign_structure_tier and
# assess_flag_severity.
#
# They derived a site's integrity tier FROM its bond valence sum, expunging on
# EXPUNGE_BVS_HIGH = 10 v.u. and EXPUNGE_BVS_LOW = 0.2. That is the wrong way
# round: the sum is computed from the coordinates, so judging the coordinates
# by the sum asks a broken structure to grade itself. It also cannot see the
# fault class that dominates every family with positional freedom. ICSD 85235
# (TbCrO3) has two oxygens 2.191 A apart against a family median of 2.750, a
# GII of 0.0047 and a chromium octahedron 0.0004 A from the measured mean; the
# old rule tiered it ACCEPT, the highest confidence in its batch.
#
# The tier now comes from the PGRM integrity gates, which ask in order whether
# the file can be read, whether the atoms can be where it says, whether the
# reference data exists, and whether the depositor's model is unambiguous.
# Geometry decides severity and chemistry is reported only for structures that
# survive it. See classify_pgrm.
#
# whatif_analysis and PLAUSIBLE_OXIDATION_STATES are KEPT. Asking which
# integer oxidation state the observed geometry supports is a question about
# the assignment, not a verdict on the structure, and PGRM has no equivalent.

PLAUSIBLE_OXIDATION_STATES = {
    'Cr': [3],
    'Mn': [2, 3, 4],
    'Fe': [2, 3],
    'Co': [2, 3, 4],
    'Ni': [2, 3],
    'Ti': [3, 4],
    'V':  [3, 4, 5],
    'Cu': [1, 2],
    'Mg': [2],
    'Al': [3],
    'Zn': [2],
    'Sc': [3],
    'Zr': [4],
    'Nb': [3, 5],
    'Mo': [4, 6],
    'Ru': [3, 4],
    'Rh': [3, 4],
    'Ir': [3, 4],
    'Ce': [3, 4],
    'Eu': [2, 3],
}


def whatif_analysis(element, bvs_value, expected_valence, anion='O'):
    """
    For FLAG-tier sites, test alternative integer oxidation states and report
    which gives the best BVS match.
    
    This implements the pragmatic position: even if we can't verify the
    depositor's valence partitioning, we can ask "does any plausible integer
    state produce a reasonable BVS?" If yes, the structure is probably fine
    and the CIF metadata just needs correcting. If no, the problem may be
    in the coordinates, not just the valence assignment.
    
    Args:
        element: Element symbol
        bvs_value: Calculated BVS (float)
        expected_valence: CIF-assigned expected valence (float)
        anion: Anion element (default 'O')
    
    Returns:
        dict with:
            best_integer_valence: int or None
            best_integer_deviation: float or None (percentage)
            candidates_tested: str (e.g. "Mn: 2(+108%), 3(+5%), 4(-28%)")
            depositor_deviation: float or None (percentage for CIF-assigned valence)
    """
    result = {
        'best_integer_valence': None,
        'best_integer_deviation': None,
        'candidates_tested': None,
        'depositor_deviation': None,
    }
    
    if bvs_value is None or element is None:
        return result
    
    # Depositor's deviation
    if expected_valence is not None and expected_valence != 0:
        result['depositor_deviation'] = round(
            (bvs_value - abs(expected_valence)) / abs(expected_valence) * 100, 1
        )
    
    candidates = PLAUSIBLE_OXIDATION_STATES.get(element, [])
    if not candidates:
        return result
    
    tested = []
    best_val = None
    best_dev = None
    
    for candidate_v in candidates:
        if candidate_v == 0:
            continue
        dev_pct = (bvs_value - candidate_v) / candidate_v * 100
        tested.append(f"{candidate_v}({dev_pct:+.0f}%)")
        
        abs_dev = abs(dev_pct)
        if best_dev is None or abs_dev < best_dev:
            best_dev = abs_dev
            best_val = candidate_v
    
    result['best_integer_valence'] = best_val
    result['best_integer_deviation'] = round(best_dev, 1) if best_dev is not None else None
    result['candidates_tested'] = f"{element}: {', '.join(tested)}" if tested else None
    
    return result


def _total_occupancy_at_position(site_label, site_occupancies_data, tol=0.001):
    """
    Total occupancy of every species sharing one crystallographic position.

    Used to express the minority/majority test as a fraction of how full the
    position actually is, rather than as an absolute occupancy.
    """
    this = site_occupancies_data.get(site_label, {})
    f0 = (this.get('fract_x'), this.get('fract_y'), this.get('fract_z'))
    if any(v is None for v in f0):
        return None
    total = 0.0
    for _lbl, _d in site_occupancies_data.items():
        f1 = (_d.get('fract_x'), _d.get('fract_y'), _d.get('fract_z'))
        if any(v is None for v in f1):
            continue
        if all(abs(a - b) < tol for a, b in zip(f0, f1)):
            total += _d.get('occupancy', 1.0)
    return total


def check_minority_species(site_label, per_atom_valences, site_occupancies_data):
    """
    Check if a site label represents a minority species on a majority-occupied site.
    
    A minority species is defined as: occupancy < 0.05 AND another element on the
    same Wyckoff position has occupancy > 0.90.
    
    This requires matching sites by fractional coordinates (since Wyckoff symbols
    are not always reliably present in ICSD CIFs).
    
    Args:
        site_label: The site label to check (e.g. 'Ti1')
        per_atom_valences: dict from extract_per_atom_valences()
        site_occupancies_data: dict from extract_site_occupancies()
    
    Returns:
        bool: True if this is a minority species on a majority-occupied site
    """
    if site_label not in per_atom_valences:
        return False
    
    this_occ = per_atom_valences[site_label].get('occupancy', 1.0)

    # v1.8.3 (B12): judge "minority" relative to how full the position is,
    # not against an absolute occupancy. In a layered oxide the alkali layer
    # is typically 0.6-0.7 occupied, so no species there ever reaches the
    # absolute 0.90 majority threshold and the rule could never fire - which
    # left genuinely impossible trace sites sitting in the ACCEPT tier.
    _total_occ = _total_occupancy_at_position(site_label, site_occupancies_data)
    if _total_occ and _total_occ > 0:
        if ge(this_occ / _total_occ, MINORITY_OCC_THRESHOLD):
            return False
    elif ge(this_occ, MINORITY_OCC_THRESHOLD):
        return False
    
    # This site has low occupancy. Check if another element at the same
    # fractional coordinates has high occupancy.
    this_site_data = site_occupancies_data.get(site_label, {})
    this_frac = (this_site_data.get('fract_x'), this_site_data.get('fract_y'), this_site_data.get('fract_z'))
    
    if any(v is None for v in this_frac):
        return False
    
    for other_label, other_data in site_occupancies_data.items():
        if other_label == site_label:
            continue
        other_frac = (other_data.get('fract_x'), other_data.get('fract_y'), other_data.get('fract_z'))
        if any(v is None for v in other_frac):
            continue
        
        # Match by fractional coordinates (within tolerance for rounding)
        if all(abs(a - b) < 0.001 for a, b in zip(this_frac, other_frac)):
            other_occ = other_data.get('occupancy', 1.0)
            _other_rel = (other_occ / _total_occ) if (_total_occ and _total_occ > 0) else other_occ
            if gt(_other_rel, MAJORITY_OCC_THRESHOLD):
                # Anti-site check: if this minority element is a majority
                # species on a DIFFERENT crystallographic site, this is
                # anti-site exchange (e.g. Na/Ti swapping between layers),
                # not a trace dopant. Anti-site disorder produces large but
                # physically meaningful BVS deviations — do not EXPUNGE.
                this_element = per_atom_valences.get(site_label, {}).get('element')
                is_antisite = False
                if this_element:
                    for check_label, check_pav in per_atom_valences.items():
                        if check_label == site_label:
                            continue
                        if check_pav.get('element') == this_element:
                            if gt(check_pav.get('occupancy', 0), MAJORITY_OCC_THRESHOLD):
                                is_antisite = True
                                break
                if not is_antisite:
                    return True
                # else: anti-site exchange — fall through to return False
    
    return False


# An anti-site is a minority ON ITS POSITION, not a trace dopant.
# MINORITY_OCC_THRESHOLD is 0.05 because it exists to catch trace species for
# the EXPUNGE rule; reusing it here found 3 of the 18 anti-site structures in
# the ICSD perovskite set, because the relative occupancies run from 2.5% to
# 29%. Fe at 25% on the La site of ICSD 7796 is unambiguously anti-site
# exchange and takes that structure to a per-species GII of 1.30.
#
# The discrimination is done by the second condition, not this one: the same
# element must be a MAJORITY on another crystallographic site. A 30% Sr on the
# La site of a substituted manganite is not anti-site exchange, because Sr is
# nowhere else in the structure, and it is correctly left alone.
ANTISITE_MINORITY_MAX = 0.50


def antisite_exchange(per_atom_valences, site_occupancies_data,
                      minority=None, majority=None):
    """
    Species that are a minority on one position and a majority on another.

    v2.0.2. check_minority_species already computes this internally, in order
    to decline to EXPUNGE it: anti-site exchange produces large but physically
    meaningful bond valence deviations, so the site is retained. That decision
    is right, but the fact was then thrown away, and it is the fact that tells
    a reader which instability index to quote.

    A 2.4% Mn on a 94.4% Tb site is asked what its sum would be in a cavity
    the majority sizes, and answers 0.83 v.u. against a formal 3. Weighted
    equally with the 97% it sits among, that single phantom takes the
    per-species GII of ICSD 215426 to 1.32; WAGII gives 0.28 and the
    site-averaged value 0.16. Across the perovskite set the two diverge by a
    factor of 3.6 below 5% minority occupancy, 2.3 between 5 and 15%, and 1.6
    between 15 and 30%, while agreeing to three decimals on all 916 ordered
    structures.

    Returns (n_antisite_sites, description) so the structure can carry the
    reason alongside the number.
    """
    minority = ANTISITE_MINORITY_MAX if minority is None else minority
    majority = MAJORITY_OCC_THRESHOLD if majority is None else majority
    found = []
    for label, data in (site_occupancies_data or {}).items():
        pav = (per_atom_valences or {}).get(label)
        if not pav:
            continue
        el = pav.get('element')
        occ = pav.get('occupancy', 1.0)
        if el is None or occ is None:
            continue
        total = _total_occupancy_at_position(label, site_occupancies_data)
        rel = (occ / total) if (total and total > 0) else occ
        # Not the dominant species on its own position.
        if ge(rel, minority):
            continue
        # minority here; is the same element a majority somewhere else?
        for other, opav in (per_atom_valences or {}).items():
            if other == label or opav.get('element') != el:
                continue
            if gt(opav.get('occupancy', 0), majority):
                found.append(f'{el} {100 * rel:.1f}% of {label}')
                break
    return len(found), ('; '.join(found) if found else None)


def check_mixed_tm_site(site_label, per_atom_valences, site_occupancies_data):
    """
    Check if a site label is part of a mixed TM occupancy site, and whether
    any TM on that site has a non-integer valence.
    
    Sites are matched by fractional coordinates.
    
    Args:
        site_label: The site label to check
        per_atom_valences: dict from extract_per_atom_valences()
        site_occupancies_data: dict from extract_site_occupancies()
    
    Returns:
        tuple: (is_mixed_tm, has_noninteger_tm)
    """
    if site_label not in per_atom_valences:
        return False, False
    
    this_elem = per_atom_valences[site_label].get('element')
    if not is_transition_metal(this_elem):
        # Not a TM site -- cannot be FLAG
        return False, False
    
    this_site_data = site_occupancies_data.get(site_label, {})
    this_frac = (this_site_data.get('fract_x'), this_site_data.get('fract_y'), this_site_data.get('fract_z'))
    
    if any(v is None for v in this_frac):
        return False, False
    
    # Find all other elements at the same position
    tm_labels_at_position = [site_label]
    
    for other_label, other_data in site_occupancies_data.items():
        if other_label == site_label:
            continue
        other_frac = (other_data.get('fract_x'), other_data.get('fract_y'), other_data.get('fract_z'))
        if any(v is None for v in other_frac):
            continue
        
        if all(abs(a - b) < 0.001 for a, b in zip(this_frac, other_frac)):
            other_elem = other_data.get('element')
            if is_transition_metal(other_elem):
                tm_labels_at_position.append(other_label)
    
    is_mixed_tm = len(tm_labels_at_position) > 1
    
    if not is_mixed_tm:
        return False, False
    
    # Check if any TM on this shared position has non-integer valence
    has_noninteger = False
    for label in tm_labels_at_position:
        if label in per_atom_valences:
            val = per_atom_valences[label].get('explicit_valence')
            if val is not None and not is_valence_integer(val):
                has_noninteger = True
                break
    
    return True, has_noninteger

def flag_same_source_entries(df):
    """
    Dataset-level pass: identify multiple ICSD entries deposited from the
    same source paper.
    
    When a single paper produces multiple ICSD entries (e.g. different
    refinement methods, different samples, phase-separated components),
    the database stores them with equal apparent authority. This function
    groups entries by source paper and flags groups with >1 structure,
    so downstream analysis can identify redundant or subsidiary depositions.
    
    Adds columns:
        source_group: identifier string (first_author|year|journal)
        source_group_size: number of ICSD entries from that paper
        source_group_codes: comma-separated list of ICSD codes in the group
        flag_multi_entry_source: True if >1 entry from the same paper
    
    Args:
        df: pandas DataFrame from Eir batch processing (site-level rows)
    
    Returns:
        df: DataFrame with new columns added
    """
    # Build structure-level lookup: one row per ICSD code
    struct_cols = ['icsd_code', 'authors', 'year', 'journal']
    available = [c for c in struct_cols if c in df.columns]

    def _no_groups(df):
        # Not enough metadata to group: every entry is a group of one
        df['source_group'] = None
        df['source_group_size'] = 1
        df['source_group_codes'] = df['icsd_code'] if 'icsd_code' in df.columns else None
        df['flag_multi_entry_source'] = False
        return df

    if 'icsd_code' not in available or 'authors' not in available:
        return _no_groups(df)

    # v2.0.46: TWO WAYS THIS STOPPED THE RUN, BOTH ON FILES THAT ARE NOT
    # ICSD EXPORTS OR ARE INCOMPLETE ONES.
    #
    # 1. No ICSD code anywhere in the run - every Rietveld CIF, and any CIF
    #    checked on its own. groupby drops the null codes, the lookup came
    #    back empty, and DataFrame.apply on an empty frame returns a frame,
    #    not a column: "Cannot set a DataFrame with multiple columns to the
    #    single column source_group". Entries without a code cannot be
    #    matched to a paper, so each is a group of one.
    # 2. A code but no author or journal. groupby().first() gives NaN, which
    #    is truthy, so `authors or ''` kept it and .split() raised. This is
    #    the "CIF without an author field" fault noted since 2.0.41. An entry
    #    with no first author is not grouped: grouping on year and journal
    #    alone would join unrelated papers.
    #
    # Neither decided a verdict. Where neither arises the groups are those
    # 2.0.45 formed.
    if not df['icsd_code'].notna().any():
        return _no_groups(df)

    other_cols = [c for c in available if c != 'icsd_code']
    struct_df = df.groupby('icsd_code')[other_cols].first().reset_index()

    def _text(v):
        return '' if v is None or (isinstance(v, float) and v != v) else str(v)

    # Build source group key from first author surname + year + journal
    def make_source_key(row):
        authors = _text(row.get('authors', ''))
        year = row.get('year', '') or ''
        journal = _text(row.get('journal', ''))
        # Extract first author surname (before first comma or space)
        first_author = authors.split(',')[0].split(' ')[0].strip().lower()
        if not first_author:
            return None
        # Normalise journal (lowercase, strip whitespace)
        journal_norm = journal.strip().lower()[:40]  # truncate for matching
        return f"{first_author}|{year}|{journal_norm}"

    struct_df['source_group'] = [make_source_key(r) for _, r in struct_df.iterrows()]
    
    # Count entries per source group
    group_counts = struct_df.groupby('source_group')['icsd_code'].agg(['count', list]).reset_index()
    group_counts.columns = ['source_group', 'source_group_size', 'group_codes_list']
    group_counts['source_group_codes'] = group_counts['group_codes_list'].apply(
        lambda x: ','.join(str(c) for c in sorted(x))
    )
    group_counts['flag_multi_entry_source'] = group_counts['source_group_size'] > 1
    group_counts = group_counts.drop(columns=['group_codes_list'])
    
    # Merge back to structure level, then to site level
    struct_df = struct_df.merge(group_counts, on='source_group', how='left')
    
    # Map to original df via icsd_code
    merge_cols = ['icsd_code', 'source_group', 'source_group_size', 
                  'source_group_codes', 'flag_multi_entry_source']
    df = df.merge(struct_df[merge_cols], on='icsd_code', how='left')

    # v2.0.46: an entry left ungrouped - no code, or no first author - is a
    # group of one, as in the no-metadata case, rather than a row of nulls.
    # Column-wise rather than by .loc, so pandas 3's string columns accept it.
    _alone = df['source_group'].isna()
    if _alone.any():
        df['source_group_size'] = df['source_group_size'].fillna(1)
        df['source_group_codes'] = (df['source_group_codes'].astype(object)
                                    .where(~_alone, df['icsd_code'].astype(object)))
        df['flag_multi_entry_source'] = (df['flag_multi_entry_source']
                                         .astype(object).where(~_alone, False))

    return df

def extract_cif_oxidation_states(cif_path):
    """
    Extract oxidation states from CIF file's _atom_type_oxidation_number loop.

    ICSD CIFs typically contain this information in a loop like:
    loop_
    _atom_type_symbol
    _atom_type_oxidation_number
    Mg2+ 2
    Al3+ 3
    O2- -2

    For mixed-valence compounds, ICSD may give a non-integer value, e.g.:
    Mn4+ 3.5     (LiMn2O4 — symbol rounded up, true value in second column)

    v1.6 change: non-integer values are preserved as floats rather than truncated.
    A third return value (type_symbol -> oxidation_number map) is added so that
    extract_per_atom_valences can override symbol-parsed integers with the true
    fractional value.

    Returns:
        tuple: (oxidation_states_dict, quality, error_message, type_map)
        - oxidation_states_dict: {element: charge} e.g., {'Li': 1, 'Mn': 3.5, 'O': -2}
        - quality: 'explicit' | 'inferred' | 'missing' | 'ambiguous'
        - error_message: None or description of issue
        - type_map: {type_symbol: oxidation_number} e.g., {'Mn4+': 3.5}
    """
    oxidation_states = {}
    type_map = {}
    quality = 'missing'
    error_message = None

    try:
        # v2.0.46: as normalise_atom_types leaves it
        lines = read_cif_text(cif_path).split('\n')
    except Exception as e:
        return {}, 'missing', f"Could not read CIF: {e}", {}

    in_atom_type_loop = False
    columns = []
    symbol_col = None
    oxidation_col = None

    for line in lines:
        line_stripped = line.strip()

        if line_stripped == 'loop_':
            in_atom_type_loop = False
            columns = []
            symbol_col = None
            oxidation_col = None
            continue

        if line_stripped.startswith('_atom_type_'):
            columns.append(line_stripped)
            col_idx = len(columns) - 1
            if line_stripped == '_atom_type_symbol':
                symbol_col = col_idx
            elif line_stripped == '_atom_type_oxidation_number':
                oxidation_col = col_idx
                in_atom_type_loop = True
            continue

        if in_atom_type_loop and columns and not line_stripped.startswith('_'):
            if not line_stripped or line_stripped.startswith('#') or line_stripped.startswith('loop_'):
                in_atom_type_loop = False
                continue

            parts = line_stripped.split()

            if symbol_col is not None and symbol_col < len(parts):
                symbol_raw = parts[symbol_col]
                element = re.sub(r'[0-9+-]+', '', symbol_raw)
                element = element.capitalize() if len(element) > 1 else element.upper()

                if oxidation_col is not None and oxidation_col < len(parts):
                    ox_str = parts[oxidation_col]
                    if ox_str not in ['?', '.']:
                        try:
                            # v1.6: preserve fractional values (e.g. 3.5 for Mn in LiMn2O4)
                            ox_float = float(ox_str)
                            if ox_float == int(ox_float):
                                oxidation = int(ox_float)
                            else:
                                oxidation = ox_float

                            type_map[symbol_raw] = oxidation

                            if element in oxidation_states:
                                if oxidation_states[element] != oxidation:
                                    quality = 'ambiguous'
                                    error_message = f"Multiple oxidation states for {element}"
                            else:
                                oxidation_states[element] = oxidation
                                if quality != 'ambiguous':
                                    quality = 'explicit'
                        except ValueError:
                            pass

    # Fallback: the charges the type symbols carry, where no loop gives
    # oxidation numbers. v2.0.46: read from the atom_site type column. This
    # used to scan every line of the file for anything shaped like 'X2+', so
    # a type written 'CO2+' gave oxygen a valence of +2 and a title or a
    # chemical name could supply valences of its own.
    if not oxidation_states:
        for _L in _cif_loops(lines):
            if '_atom_site_type_symbol' not in _L[2] or _L[3] is None:
                continue
            _k = _L[2].index('_atom_site_type_symbol')
            for _r in _L[3]:
                _t = _cif_tokens(lines[_r])
                if len(_t) != len(_L[2]):
                    continue
                _el, _ch = parse_atom_symbol(_t[_k])
                if _el is None or _ch is None:
                    continue
                _el = 'H' if _el == 'D' else _el
                if _el not in oxidation_states:
                    oxidation_states[_el] = int(_ch) if _ch == int(_ch) else _ch
                    quality = 'inferred'

    if not oxidation_states:
        quality = 'missing'
        error_message = "No oxidation state information found in CIF"

    return oxidation_states, quality, error_message, type_map


def parse_chemical_formula(formula):
    """
    Parse chemical formula string into element counts.
    
    Handles formats like:
    - "Mg1 Al2 O4" (space-separated)
    - "MgAl2O4" (no spaces)
    - "Fe3O4"
    - "Li0.5Mn1.5O4"
    
    Returns:
        dict: {element: count} e.g., {'Mg': 1.0, 'Al': 2.0, 'O': 4.0}
    """
    if not formula:
        return {}
    
    # Clean up formula
    formula = formula.strip().replace("'", "").replace('"', '')
    
    # Pattern: Element followed by optional number (including decimals)
    pattern = r'([A-Z][a-z]?)(\d*\.?\d*)'
    
    elements = {}
    for match in re.finditer(pattern, formula):
        element = match.group(1)
        count_str = match.group(2)
        
        if element:  # Skip empty matches
            count = float(count_str) if count_str else 1.0
            elements[element] = elements.get(element, 0) + count
    
    return elements


def detect_mixed_valence_requirement(formula, oxidation_states):
    """
    Detect if a formula requires mixed valence to achieve charge balance.
    
    For example:
    - Fe3O4 with Fe3+ and O2-: 3(+3) + 4(-2) = +1 != 0 -> needs Fe2+/Fe3+ mix
    - MgAl2O4 with Mg2+, Al3+, O2-: +2 + 2(+3) + 4(-2) = 0 -> OK
    
    Returns:
        dict with:
        - requires_mixed_valence: bool
        - charge_balance_error: float (should be 0 for valid structure)
        - problematic_elements: list of elements that might need mixed valence
        - suggested_average_charges: dict of {element: required_average_charge}
    """
    result = {
        'requires_mixed_valence': False,
        'charge_balance_error': 0.0,
        'problematic_elements': [],
        'suggested_average_charges': {}
    }
    
    elements = parse_chemical_formula(formula)
    if not elements or not oxidation_states:
        return result
    
    # Separate cations and anions
    anion_elements = {e for e in elements if e in KNOWN_ANIONS}
    cation_elements = {e for e in elements if e not in KNOWN_ANIONS}
    
    # Calculate total anion charge
    anion_charge = sum(
        elements.get(e, 0) * KNOWN_ANIONS.get(e, 0)
        for e in anion_elements
    )
    
    # Calculate total cation charge based on provided oxidation states
    cation_charge = 0
    for elem in cation_elements:
        if elem in oxidation_states:
            cation_charge += elements.get(elem, 0) * oxidation_states[elem]
    
    # Check charge balance
    total_charge = cation_charge + anion_charge

    # v1.8.8: round before storing and comparing. The inputs are occupancies
    # quoted to two or three decimals and valences to three, so digits beyond
    # the sixth are float noise, and reporting an error of
    # 0.010000000000000675 is worse than useless - it invites the reader to
    # believe a precision that is not there.
    total_charge = round(total_charge, 6)
    result['charge_balance_error'] = total_charge

    if gt(abs(total_charge), CHARGE_BALANCE_TOLERANCE):  # Not balanced
        result['requires_mixed_valence'] = True
        
        # Identify which elements might need mixed valence
        for elem in cation_elements:
            if elem in VARIABLE_VALENCE_ELEMENTS:
                result['problematic_elements'].append(elem)
                
                # Calculate what average charge would be needed
                # If we remove this element's contribution and solve for it
                other_cation_charge = sum(
                    elements.get(e, 0) * oxidation_states.get(e, 0)
                    for e in cation_elements if e != elem
                )
                
                # Required charge from this element to balance
                required_charge = -anion_charge - other_cation_charge
                elem_count = elements.get(elem, 1)
                if elem_count > 0:
                    required_avg = required_charge / elem_count
                    result['suggested_average_charges'][elem] = round(required_avg, 2)
    
    return result


def flag_oxidation_state_issues(cif_path, formula):
    """
    Comprehensive check for oxidation state issues (Type 7 errors).
    
    Returns:
        dict with:
        - has_type7_error: bool
        - error_code: str or None
        - error_message: str or None
        - oxidation_states: dict from CIF
        - quality: str
        - mixed_valence_info: dict
    """
    result = {
        'has_type7_error': False,
        'error_code': None,
        'error_message': None,
        'oxidation_states': {},
        'quality': 'unknown',
        'mixed_valence_info': {}
    }
    
    # Extract oxidation states from CIF
    ox_states, quality, error_msg, _ = extract_cif_oxidation_states(cif_path)
    result['oxidation_states'] = ox_states
    result['quality'] = quality
    
    # Check for missing oxidation states
    if quality == 'missing':
        result['has_type7_error'] = True
        result['error_code'] = 'TYPE7_NO_OXIDATION_STATES'
        result['error_message'] = error_msg or "CIF lacks oxidation state information"
        return result
    
    # Check for ambiguous (multiple) oxidation states
    if quality == 'ambiguous':
        result['has_type7_error'] = True
        result['error_code'] = 'TYPE7_EXPLICIT_MIXED_VALENCE'
        result['error_message'] = error_msg or "CIF specifies multiple oxidation states for same element"
        return result
    
    # Check if formula requires mixed valence for charge balance
    mixed_valence_info = detect_mixed_valence_requirement(formula, ox_states)
    result['mixed_valence_info'] = mixed_valence_info
    
    if mixed_valence_info['requires_mixed_valence']:
        result['has_type7_error'] = True
        
        if abs(mixed_valence_info['charge_balance_error']) > 0.5:
            result['error_code'] = 'TYPE7_CHARGE_IMBALANCE'
            result['error_message'] = (
                f"Charge imbalance of {mixed_valence_info['charge_balance_error']:+.1f} "
                f"cannot be resolved with given oxidation states"
            )
        else:
            result['error_code'] = 'TYPE7_REQUIRES_MIXED_VALENCE'
            problematic = ', '.join(mixed_valence_info['problematic_elements'])
            result['error_message'] = (
                f"Charge balance requires mixed valence for: {problematic}"
            )
    
    return result

def flag_all_error_types(cif_path, formula, site_data):
    """
    Flag all detectable error types (2-7) for a structure.
    Based on taxonomy from Sherwood (2026) Dalton Trans.
    
    Types:
        2: Missing BVS parameters
        3: Vacancy disorder / nonstoichiometric
        4: Heterovalent disorder ΔV ≥ 2
        5: Homovalent / site disorder
        6A: Pre-modern techniques (pre-1980)
        7: Mixed valence (handled separately)
    
    Returns:
        dict with flag_type2 through flag_type6 and error descriptions
    """
    flags = {
        'flag_type2': False,
        'flag_type3': False,
        'flag_type4': False,
        'flag_type5': False,
        'flag_type6': False,
        'flag_type8': False,
        'error_types_detected': [],
        'error_type_details': None,
    }
    
    details = []
    
    # ========================================================================
    # TYPE 2: Missing BVS parameters
    # ========================================================================
    if site_data:
        for site in site_data:
            if site.get('bvs') is None and site.get('element') is not None:
                elem = site.get('element')
                valence = site.get('valence')
                if elem and valence:
                    # Check if parameters exist
                    R0, B = get_bv_parameters_fractional(elem, valence, 'O')
                    if R0 is None:
                        flags['flag_type2'] = True
                        if 'TYPE2' not in flags['error_types_detected']:
                            flags['error_types_detected'].append('TYPE2')
                            details.append(f"T2:No BVS params {elem}{valence:+g}-O")
    
    # ========================================================================
    # TYPE 3: Vacancy disorder / nonstoichiometric
    # ========================================================================
    if formula:
        try:
            parsed = parse_chemical_formula(formula)
            for elem, count in parsed.items():
                if count != int(count) and abs(count - round(count)) > 0.05:
                    flags['flag_type3'] = True
                    if 'TYPE3' not in flags['error_types_detected']:
                        flags['error_types_detected'].append('TYPE3')
                        details.append(f"T3:Nonstoich {elem}={count:.2f}")
                    break
        except (ValueError, TypeError, AttributeError, KeyError) as _e:
            # v2.0.11: a crash here used to drop the flag and leave the
            # structure looking clean. Under PGRM that silently downgrades
            # M1 to ACCEPT.
            flags['error_types_detected'].append('TYPE3_UNTESTED')
            details.append(f"T3:not tested ({type(_e).__name__})")
    
    # ========================================================================
    # TYPE 5: Significant site disorder (sub-unity total occupancy = vacancies)
    # ========================================================================
    if site_data:
        for site in site_data:
            occ_str = site.get('occupancy_string', '')
            if occ_str and occ_str != 'unknown':
                try:
                    # Parse "Fe:0.800,Ni:0.200" format → sum individual occupancies
                    total_occ = sum(
                        float(part.split(':')[1]) 
                        for part in occ_str.split(',') 
                        if ':' in part
                    )
                    if lt(total_occ, 0.90):
                        flags['flag_type5'] = True
                        if 'TYPE5' not in flags['error_types_detected']:
                            flags['error_types_detected'].append('TYPE5')
                            elem = site.get('element', '?')
                            details.append(f"T5:Disorder {elem} total_occ={total_occ:.2f}")
                        break
                except (ValueError, IndexError):
                    pass
    
    # ========================================================================
    # TYPE 6A: Pre-modern techniques (pre-1980)
    # ========================================================================
    try:
        with open(cif_path, 'r', errors='ignore') as f:
            content = f.read()
        
        year = None
        # Try multiple year fields
        for pattern in [r'_citation_year\s+(\d{4})', 
                        r'_journal_year\s+(\d{4})',
                        r"primary\s+'[^']+'\s+(\d{4})"]:
            match = re.search(pattern, content)
            if match:
                year = int(match.group(1))
                break
        
        if year and year < 1980:
            flags['flag_type6'] = True
            if 'TYPE6' not in flags['error_types_detected']:
                flags['error_types_detected'].append('TYPE6')
                details.append(f"T6:Pre-modern ({year})")
    except (ValueError, TypeError, AttributeError, IndexError) as _e:
        flags['error_types_detected'].append('TYPE6_UNTESTED')
        details.append(f"T6:not tested ({type(_e).__name__})")
    
    # ========================================================================
    # TYPE 8: Shannon radii violation (>7% deviation for pure-occupancy sites)
    # Literature basis: <5% = accurate (ML radii papers), 7% catches errors
    # while allowing natural variation from polyhedral distortion
    # ========================================================================
    SHANNON_DEVIATION_THRESHOLD = 7.0  # percent
    
    if site_data:
        type8_sites = []
        for site in site_data:
            # Only flag pure-occupancy sites (single cation, no mixing)
            has_mixed = site.get('has_mixed_occupancy', False)
            n_elements = site.get('n_elements_at_site', 1)
            
            if not has_mixed and n_elements == 1:
                shannon_diff = site.get('shannon_diff')
                if shannon_diff is not None and abs(shannon_diff) > SHANNON_DEVIATION_THRESHOLD:
                    elem = site.get('element', '?')
                    type8_sites.append(f"{elem}:{shannon_diff:+.1f}%")
        
        if type8_sites:
            flags['flag_type8'] = True
            if 'TYPE8' not in flags['error_types_detected']:
                flags['error_types_detected'].append('TYPE8')
                details.append(f"T8:Shannon violation {','.join(type8_sites)}")
    
    # ========================================================================
    # Compile results
    # ========================================================================
    flags['error_types_detected'] = ','.join(flags['error_types_detected']) if flags['error_types_detected'] else None
    flags['error_type_details'] = '; '.join(details) if details else None
    
    return flags

def parse_atom_type_with_valence(atom_type_raw):
    """
    Parse atom type symbol to extract element AND explicit valence.
    
    Examples:
        "Fe3+" -> ('Fe', 3)
        "Fe2+" -> ('Fe', 2)
        "O2-"  -> ('O', -2)
        "Mn"   -> ('Mn', None)  # No explicit valence
    
    Returns:
        tuple: (element_symbol, explicit_valence or None)
    """
    if not atom_type_raw:
        return None, None
    
    atom_type_raw = atom_type_raw.strip()
    
    # Pattern: Element + number + charge sign (Fe3+, O2-, Mn2+)
    match = re.match(r'^([A-Z][a-z]?)(\d+)?([+-])$', atom_type_raw)
    
    if match:
        element = match.group(1)
        number = match.group(2)
        sign = match.group(3)
        
        if number and sign:
            valence = int(number) if sign == '+' else -int(number)
            return element, valence
        elif sign:
            valence = 1 if sign == '+' else -1
            return element, valence
    
    # Alternative: charge before number (Fe+3, O-2)
    match = re.match(r'^([A-Z][a-z]?)([+-])(\d+)$', atom_type_raw)
    if match:
        element = match.group(1)
        sign = match.group(2)
        number = match.group(3)
        valence = int(number) if sign == '+' else -int(number)
        return element, valence
    
    # No explicit valence - just extract element
    element = re.sub(r'[0-9+-]+$', '', atom_type_raw)
    element = element.capitalize() if len(element) > 1 else element.upper()
    
    return element, None


def extract_per_atom_valences(cif_path):
    """
    Extract explicit valences from each atom row in the CIF.

    For mixed-valence CIFs like jacobsite:
        Fe2 Fe2+ 16 d 0.625 0.625 0.625 . 0.375
        Fe3 Fe3+ 16 d 0.625 0.625 0.625 . 0.56

    v1.6 change: when the _atom_type loop contains a more precise (fractional)
    oxidation number than the type symbol suggests — as in LiMn2O4 where the
    symbol "Mn4+" labels a value of 3.5 — the fractional value is preferred.

    Returns:
        dict: {site_label: {'element': str, 'explicit_valence': int|float|None,
                           'occupancy': float, 'type_symbol': str}}
    """
    result = {}

    # v1.6: Read the _atom_type loop first so we have the true valence map
    try:
        _, _, _, type_map = extract_cif_oxidation_states(cif_path)
    except Exception:
        type_map = {}

    try:
        content = read_cif_text(cif_path)      # v2.0.46
    except (OSError, UnicodeDecodeError) as _e:
        # v2.0.11: recorded, not swallowed. A file that could not be read is
        # not a file with nothing in it.
        _note_read_failure(cif_path, 'extract_per_atom_valences', _e)
        return result

    lines = content.split('\n')

    in_atom_loop = False
    columns = []
    label_col = type_col = occ_col = None

    for line in lines:
        line_stripped = line.strip()

        if line_stripped.startswith('loop_'):
            in_atom_loop = False
            columns = []
            label_col = type_col = occ_col = None
            continue

        if line_stripped.startswith('_atom_site_'):
            col_idx = len(columns)
            columns.append(line_stripped)

            if line_stripped == '_atom_site_label':
                label_col = col_idx
            elif line_stripped == '_atom_site_type_symbol':
                type_col = col_idx
            elif line_stripped == '_atom_site_occupancy':
                occ_col = col_idx

            in_atom_loop = True
            continue

        if in_atom_loop and columns and not line_stripped.startswith('_'):
            if not line_stripped or line_stripped.startswith('#') or line_stripped.startswith('loop_'):
                in_atom_loop = False
                continue

            parts = line_stripped.split()

            label = parts[label_col] if label_col is not None and label_col < len(parts) else None

            type_symbol = None
            element, explicit_valence = None, None
            if type_col is not None and type_col < len(parts):
                type_symbol = parts[type_col]
                element, explicit_valence = parse_atom_type_with_valence(type_symbol)

                # v1.6: if the _atom_type loop has a more precise value, use it.
                # This is the key fix for LiMn2O4 "Mn4+" where the true value is 3.5.
                if type_symbol in type_map:
                    loop_valence = type_map[type_symbol]
                    # Prefer the loop value whenever it differs from the symbol-parsed one
                    # (handles both fractional overrides and any other mismatches)
                    if explicit_valence is None or loop_valence != explicit_valence:
                        explicit_valence = loop_valence

            occupancy = 1.0
            if occ_col is not None and occ_col < len(parts):
                try:
                    occ_str = parts[occ_col]
                    if occ_str not in ['?', '.']:
                        occupancy = float(occ_str.split('(')[0])
                except (ValueError, TypeError, IndexError):
                    pass

            if label and element:
                result[label] = {
                    'element': element,
                    'explicit_valence': explicit_valence,
                    'occupancy': occupancy,
                    'type_symbol': type_symbol,
                }

    return result

def get_oxidation_states_for_analysis(cif_path, formula, config_states=None):
    """
    Get oxidation states with priority: config > CIF explicit > CIF inferred > None.
    
    This is the main entry point for oxidation state determination in Eir 1.4.
    
    Args:
        cif_path: Path to CIF file
        formula: Chemical formula string
        config_states: Dict of {element: charge} from config.json (highest priority)
    
    Returns:
        tuple: (oxidation_states, source, type7_flag_result)
        - oxidation_states: dict or None
        - source: 'config' | 'cif_explicit' | 'cif_inferred' | None
        - type7_flag_result: dict from flag_oxidation_state_issues
    """
    # Always check for Type 7 issues
    type7_result = flag_oxidation_state_issues(cif_path, formula)
    
    # Priority 1: Config file (user override)
    if config_states:
        return config_states, 'config', type7_result
    
    # Priority 2: CIF explicit oxidation states
    if type7_result['quality'] == 'explicit':
        return type7_result['oxidation_states'], 'cif_explicit', type7_result
    
    # Priority 3: CIF inferred oxidation states
    if type7_result['quality'] == 'inferred':
        return type7_result['oxidation_states'], 'cif_inferred', type7_result
    
    # No oxidation states available
    return None, None, type7_result


# ============================================================================
# ENHANCED STRUCTURAL PARAMETER EXTRACTION (NEW IN v1.4)
# ============================================================================

def _read_it_number(cif_path):
    """Space-group IT number from a CIF, or None."""
    try:
        with open(cif_path, 'r', encoding='utf-8', errors='replace') as f:
            txt = f.read()
    except Exception:
        return None
    m = (re.search(r'_space_group_IT_number\s+(\d+)', txt) or
         re.search(r'_symmetry_Int_Tables_number\s+(\d+)', txt))
    return int(m.group(1)) if m else None


def extract_anion_parameter(cif_path, formula=None):
    """
    Extract anion positional parameters from a spinel CIF file.
    
    v1.7.3: Generalised anion parameter framework for all spinel space groups.
    
    Cubic Fd-3m:     32e (x, x, x)        -> 1 free parameter (u)
    Ordered P4332:   24e (x, 0, 0) + 8c   -> 2 sites, 2 parameters
    Tetragonal I41/amd: 16h (0, y, z)      -> 2 free parameters
    Orthorhombic Fddd:  32h (x, y, z)      -> 3 free parameters
    Orthorhombic Imma:  8h (0, y, z)       -> 2 free parameters
    
    New metrics:
        u_eff:   Effective anion parameter (comparable across all space groups)
        delta_u: Anion sublattice anisotropy (0 for cubic, >0 for distorted)
    
    For Fd-3m, detects origin choice and standardises to origin 2.
    
    Returns:
        dict with: u_parameter, u_parameter_raw, u_deviation, origin_choice,
                   anion_x, anion_y, anion_z, anion_wyckoff, anion_multiplicity,
                   u_eff, delta_u, anion_site_count, anion_x_2/y_2/z_2/wyckoff_2
    """
    result = {
        'u_parameter': None,           # Cubic Fd-3m only: standardised to origin 2
        'u_parameter_raw': None,       # As extracted from CIF (before origin correction)
        'pyrochlore_48f_x': None,      # Fd-3m 48f free coordinate (pyrochlore)
        'pyrochlore_fluorite_limit': None,  # True at x = 3/8, where ordering vanishes
        'u_deviation': None,           # Deviation from ideal (0.25)
        'origin_choice': None,         # 1 or 2 (detected, cubic only)
        'anion_x': None,              # Primary anion site fractional x
        'anion_y': None,              # Primary anion site fractional y
        'anion_z': None,              # Primary anion site fractional z
        'anion_wyckoff': None,         # Full Wyckoff symbol e.g. "32e", "16h"
        'anion_multiplicity': None,    # Just the number e.g. 32
        'anion_wyckoff_letter': None,  # Just the letter e.g. "e"
        # v1.7.3: Generalised anion parameters
        'u_eff': None,                 # Effective u (all space groups)
        'delta_u': None,              # Anion sublattice anisotropy
        'anion_site_count': None,      # Number of distinct anion Wyckoff sites
        'anion_x_2': None,            # Second anion site x (P4332 only)
        'anion_y_2': None,            # Second anion site y
        'anion_z_2': None,            # Second anion site z
        'anion_wyckoff_2': None,       # Second anion Wyckoff symbol
    }
    
    # Determine anion elements. Fourth hand-written copy of the same nine
    # species until v2.0.13; now the single PROVISIONAL_ANIONS set, narrowed
    # below when the formula says which anion this structure actually has.
    anion_elements = set(PROVISIONAL_ANIONS)
    if formula:
        formula_elements = set(re.findall(r'[A-Z][a-z]?', formula))
        if formula_elements & {'S', 'Se', 'Te'}:
            anion_elements = {'S', 'Se', 'Te'}
        elif 'O' in formula_elements:
            anion_elements = {'O'}
    
    try:
        content = read_cif_text(cif_path)      # v2.0.46
    except (OSError, UnicodeDecodeError) as _e:
        # v2.0.11: recorded, not swallowed. A file that could not be read is
        # not a file with nothing in it.
        _note_read_failure(cif_path, 'extract_anion_parameter', _e)
        return result

    lines = content.split('\n')
    
    # Parse atom_site loop
    in_atom_loop = False
    columns = []
    label_col = type_col = x_col = y_col = z_col = None
    wyckoff_col = multiplicity_col = None
    
    for line in lines:
        line_stripped = line.strip()
        
        if line_stripped.startswith('loop_'):
            in_atom_loop = False
            columns = []
            label_col = type_col = x_col = y_col = z_col = None
            wyckoff_col = multiplicity_col = None
            continue
        
        if line_stripped.startswith('_atom_site_'):
            col_idx = len(columns)
            columns.append(line_stripped)
            
            if line_stripped == '_atom_site_label':
                label_col = col_idx
            elif line_stripped == '_atom_site_type_symbol':
                type_col = col_idx
            elif line_stripped == '_atom_site_fract_x':
                x_col = col_idx
            elif line_stripped == '_atom_site_fract_y':
                y_col = col_idx
            elif line_stripped == '_atom_site_fract_z':
                z_col = col_idx
            elif line_stripped == '_atom_site_Wyckoff_symbol':
                wyckoff_col = col_idx
            elif line_stripped == '_atom_site_symmetry_multiplicity':
                multiplicity_col = col_idx
            
            in_atom_loop = True
            continue
        
        if in_atom_loop and columns and not line_stripped.startswith('_'):
            if not line_stripped or line_stripped.startswith('#') or line_stripped.startswith('loop_'):
                in_atom_loop = False
                continue
            
            parts = line_stripped.split()
            required_cols = [c for c in [label_col, type_col, x_col, y_col, z_col] if c is not None]
            if not required_cols or len(parts) < max(required_cols) + 1:
                continue
            
            # Get element type
            elem = None
            if type_col is not None and type_col < len(parts):
                elem_raw = parts[type_col]
                elem = re.sub(r'[0-9+-]+', '', elem_raw)
                elem = elem.capitalize() if len(elem) > 1 else elem.upper()
            elif label_col is not None and label_col < len(parts):
                label = parts[label_col]
                elem_match = re.match(r'([A-Z][a-z]?)', label)
                elem = elem_match.group(1) if elem_match else None
            
            if elem not in anion_elements:
                continue
            
            # ---- Found an anion site ----
            
            def parse_coord(val_str):
                """Parse coordinate value, handling ESDs in parentheses."""
                if not val_str or val_str in ['?', '.']:
                    return None
                match = re.match(r'^([+-]?\d*\.?\d+)', val_str)
                if match:
                    try:
                        return float(match.group(1))
                    except (ValueError, TypeError):
                        return None
                return None
            
            this_x = parse_coord(parts[x_col]) if x_col is not None and x_col < len(parts) else None
            this_y = parse_coord(parts[y_col]) if y_col is not None and y_col < len(parts) else None
            this_z = parse_coord(parts[z_col]) if z_col is not None and z_col < len(parts) else None
            
            # Extract Wyckoff info for this site
            this_wyckoff_letter = parts[wyckoff_col] if wyckoff_col is not None and wyckoff_col < len(parts) else None
            this_multiplicity = None
            if multiplicity_col is not None and multiplicity_col < len(parts):
                try:
                    this_multiplicity = int(parts[multiplicity_col])
                except (ValueError, TypeError, IndexError):
                    pass
            
            # Build full Wyckoff symbol
            if this_multiplicity is not None and this_wyckoff_letter is not None:
                this_wyckoff = f"{this_multiplicity}{this_wyckoff_letter}"
            elif this_wyckoff_letter is not None:
                # Fallback multiplicity lookup (common spinel space groups)
                wyckoff_multiplicities = {
                    'a': 8, 'b': 8, 'c': 16, 'd': 16, 'e': 32, 'f': 48,
                    'g': 48, 'h': 96, 'i': 96, 'j': 192
                }
                mult = wyckoff_multiplicities.get(this_wyckoff_letter.lower())
                if mult:
                    this_wyckoff = f"{mult}{this_wyckoff_letter}"
                    this_multiplicity = mult
                else:
                    this_wyckoff = this_wyckoff_letter
            else:
                this_wyckoff = None
            
            # Store to primary or secondary anion site
            if result['anion_x'] is None:
                # First anion site
                result['anion_x'] = this_x
                result['anion_y'] = this_y
                result['anion_z'] = this_z
                result['anion_wyckoff'] = this_wyckoff
                result['anion_wyckoff_letter'] = this_wyckoff_letter
                result['anion_multiplicity'] = this_multiplicity
                result['anion_site_count'] = 1
            elif result['anion_x_2'] is None:
                # Second anion site (e.g. P4332: 24e + 8c)
                result['anion_x_2'] = this_x
                result['anion_y_2'] = this_y
                result['anion_z_2'] = this_z
                result['anion_wyckoff_2'] = this_wyckoff
                result['anion_site_count'] = 2
            else:
                break  # Two anion sites found, stop
            continue  # Keep looking for additional anion sites
    
    # =========================================================================
    # Generalised anion parameter calculation (v1.7.3)
    # =========================================================================
    ax = result['anion_x']
    ay = result['anion_y']
    az = result['anion_z']
    # v2.0.12: choose which anion site carries the FREE parameter, rather
    # than whichever the CIF happened to list first.
    #
    # In Fd-3m the 48f anion has one free coordinate and the 8b anion is
    # fixed at (3/8,3/8,3/8) by symmetry, so 8b's coordinate carries no
    # information at all. Taking the first-listed site reported
    # u_parameter_raw = 0.375 and u_deviation = 0.000 for every pyrochlore
    # tested, whether its 48f x was 0.375 (ICSD 26799, at the fluorite
    # limit) or -0.0788 (ICSD 14242 and 42702, ordinary). The one entry
    # where 0.375 means something was indistinguishable from the two where
    # it means nothing.
    #
    # The site with the higher multiplicity is the one with positional
    # freedom in every structure type this function handles: 48f over 8b,
    # 32e over 8b, 24e over 8c.
    _m1 = result.get('anion_multiplicity')
    _m2 = None
    _wy2 = result.get('anion_wyckoff_2') or ''
    _mm = re.match(r'(\d+)', _wy2)
    if _mm:
        _m2 = int(_mm.group(1))
    if _m1 is not None and _m2 is not None and _m2 > _m1:
        for _a, _b in (('anion_x', 'anion_x_2'), ('anion_y', 'anion_y_2'),
                       ('anion_z', 'anion_z_2'),
                       ('anion_wyckoff', 'anion_wyckoff_2')):
            result[_a], result[_b] = result[_b], result[_a]
        result['anion_multiplicity'] = _m2
        _lm = re.match(r'\d+([a-z])', result['anion_wyckoff'] or '')
        result['anion_wyckoff_letter'] = _lm.group(1) if _lm else None
        result['anion_site_swapped'] = True
    else:
        result['anion_site_swapped'] = False

    # The swap above rewrote result; ax/ay/az were read from it earlier and
    # must be refreshed or the derivation below silently uses the old site.
    ax = result.get('anion_x')
    ay = result.get('anion_y')
    az = result.get('anion_z')

    wy = result.get('anion_wyckoff', '') or ''

    # v1.8.3 (B2): only assign an anion parameter for structure types where one
    # is defined. On an O3 layered oxide the cubic branch could latch onto an
    # anion at (0, 0, z) and report u = 0.0000 with u_deviation = -0.2500,
    # discarding the meaningful z. The site coordinates are still recorded;
    # only the spinel-specific parameters are withheld.
    _spinel_it_numbers = {227, 212, 213, 141, 70, 74}
    _it = _read_it_number(cif_path)
    result['u_parameter_applicable'] = (_it in _spinel_it_numbers) if _it else None
    if _it is not None and _it not in _spinel_it_numbers:
        result['u_note'] = (f'not a spinel-type space group (IT {_it}); '
                            'anion parameter not defined')
        return result

    if ax is not None:
        
        # ----- Cubic Fd-3m: 32e (x, x, x) -> single u parameter -----
        if '32e' in wy or (ay is not None and az is not None 
                           and abs(ax - ay) < 0.001 and abs(ax - az) < 0.001
                           and '16h' not in wy and '8h' not in wy):
            u_raw = ax
            result['u_parameter_raw'] = u_raw
            
            # Detect origin choice based on u value
            # Origin 1 (S): u ~ 0.375 (range 0.35-0.42)
            # Origin 2 (Z): u ~ 0.250 (range 0.23-0.30)
            if u_raw > 0.32:
                result['origin_choice'] = 1
                u_standardised = u_raw - 0.125
            else:
                result['origin_choice'] = 2
                u_standardised = u_raw
            
            result['u_parameter'] = round(u_standardised, 4)
            result['u_deviation'] = round(u_standardised - 0.25, 4)
            result['u_eff'] = result['u_parameter']
            result['delta_u'] = 0.0
        
        # ----- Tetragonal I41/amd: 16h (0, y, z) -> two parameters -----
        elif '16h' in wy or '8h' in wy:
            if ay is not None and az is not None:
                result['u_eff'] = round((ay + az) / 2, 4)
                result['delta_u'] = round(abs(ay - az), 4)
                # u_parameter left as None (cubic u not defined for tetragonal)
                # u_deviation computed from u_eff for cross-system comparison
                result['u_deviation'] = round(result['u_eff'] - 0.25, 4)
        
        # ----- Ordered cubic P4332: 24e + 8c (two distinct anion sites) -----
        elif '24e' in wy or '8c' in wy:
            ax2 = result.get('anion_x_2')
            ay2 = result.get('anion_y_2')
            az2 = result.get('anion_z_2')
            wy2 = result.get('anion_wyckoff_2', '') or ''
            
            # 8c site: coords (x, x, x), so u = x
            # 24e site: coords (x, 0, 0), so the free param is x
            u_8c = None
            u_24e = None
            
            if '8c' in wy:
                u_8c = ax
                if ax2 is not None and '24e' in wy2:
                    u_24e = ax2
                elif ax2 is not None:
                    u_24e = ax2  # Assume second site is 24e
            elif '24e' in wy:
                u_24e = ax
                if ax2 is not None and '8c' in wy2:
                    u_8c = ax2
                elif ax2 is not None:
                    u_8c = ax2  # Assume second site is 8c
            
            # Effective u: weighted by multiplicity (24e = 75%, 8c = 25%)
            if u_24e is not None and u_8c is not None:
                result['u_eff'] = round((3 * u_24e + u_8c) / 4, 4)
                result['delta_u'] = round(abs(u_24e - u_8c), 4)
                result['u_deviation'] = round(result['u_eff'] - 0.25, 4)
            elif u_8c is not None:
                # Only 8c found (unusual but handle gracefully)
                result['u_eff'] = round(u_8c, 4)
                result['u_parameter'] = round(u_8c, 4)
                result['u_deviation'] = round(u_8c - 0.25, 4)
            elif u_24e is not None:
                result['u_eff'] = round(u_24e, 4)
                result['u_deviation'] = round(u_24e - 0.25, 4)
        
        # ----- Orthorhombic Fddd: 32h (x, y, z) -> three parameters -----
        elif '32h' in wy:
            if ay is not None and az is not None:
                result['u_eff'] = round((ax + ay + az) / 3, 4)
                result['delta_u'] = round(max(abs(ax - ay), abs(ay - az), abs(ax - az)), 4)
                result['u_deviation'] = round(result['u_eff'] - 0.25, 4)
        
        # ----- Fd-3m 48f (x, 1/8, 1/8): PYROCHLORE, not a spinel u -----
        # This function is a spinel anion-parameter extractor and Fd-3m is
        # shared by both types, so a pyrochlore used to fall through to the
        # cubic fallback below and have its 48f x reported as a spinel u.
        # They are different quantities: the spinel u describes how far the
        # 32e anion sits from the ideal cubic close packing, the pyrochlore
        # 48f x describes the trigonal distortion of the B-site octahedron.
        # Standardising one against 0.25 says nothing about the other.
        #
        # x = 0.375 is the ideal DEFECT FLUORITE value, at which the
        # pyrochlore ordering vanishes: every A-O and B-O distance becomes
        # equal. ICSD 26799 (Nd2Zr2O7) is deposited at x = 0.375(7), which is
        # a phase-boundary statement rather than a fault, and it is why that
        # entry alone was symmetric under the origin-choice test.
        elif '48f' in wy:
            result['pyrochlore_48f_x'] = ax
            result['pyrochlore_fluorite_limit'] = (
                ax is not None and abs(ax - 0.375) < 0.005)
            result['u_note'] = ('Fd-3m 48f: pyrochlore anion parameter, not the spinel u; reported as pyrochlore_48f_x')

        # ----- Fallback: attempt cubic assumption -----
        else:
            u_raw = ax
            result['u_parameter_raw'] = u_raw
            if u_raw > 0.32:
                result['origin_choice'] = 1
                u_standardised = u_raw - 0.125
            else:
                result['origin_choice'] = 2
                u_standardised = u_raw
            result['u_parameter'] = round(u_standardised, 4)
            result['u_deviation'] = round(u_standardised - 0.25, 4)
            result['u_eff'] = result['u_parameter']
    
    return result


def extract_site_occupancies(cif_path):
    """
    Extract site occupancies with full detail.
    
    Returns:
        dict: {site_label: {element, occupancy, wyckoff, fract_x, fract_y, fract_z}}
    """
    result = {}
    
    try:
        lines = [l + '\n' for l in read_cif_text(cif_path).split('\n')]  # v2.0.46
    except (OSError, UnicodeDecodeError) as _e:
        # v2.0.11: recorded, not swallowed. A file that could not be read is
        # not a file with nothing in it.
        _note_read_failure(cif_path, 'extract_site_occupancies', _e)
        return result

    in_atom_loop = False
    columns = []
    col_indices = {}
    
    for line in lines:
        line_stripped = line.strip()
        
        if line_stripped == 'loop_':
            in_atom_loop = False
            columns = []
            col_indices = {}
            continue
        
        if line_stripped.startswith('_atom_site_'):
            columns.append(line_stripped)
            col_idx = len(columns) - 1
            tag_map = {
                '_atom_site_label': 'label',
                '_atom_site_type_symbol': 'type',
                '_atom_site_occupancy': 'occupancy',
                '_atom_site_fract_x': 'fract_x',
                '_atom_site_fract_y': 'fract_y',
                '_atom_site_fract_z': 'fract_z',
                '_atom_site_Wyckoff_symbol': 'wyckoff',
                '_atom_site_symmetry_multiplicity': 'multiplicity',
            }
            for tag, name in tag_map.items():
                if line_stripped == tag:
                    col_indices[name] = col_idx
            in_atom_loop = True
            continue
        
        if in_atom_loop and columns and not line_stripped.startswith('_'):
            if not line_stripped or line_stripped.startswith('#') or line_stripped.startswith('loop_'):
                in_atom_loop = False
                continue
            
            parts = line_stripped.split()
            
            def get_val(name):
                if name in col_indices and col_indices[name] < len(parts):
                    return parts[col_indices[name]]
                return None
            
            def parse_numeric(val_str):
                if not val_str or val_str in ['?', '.']:
                    return None, None
                match = re.match(r'^([+-]?\d+\.?\d*)\((\d+)\)$', val_str)
                if match:
                    val = float(match.group(1))
                    if '.' in match.group(1):
                        dec_places = len(match.group(1).split('.')[1])
                        esd = int(match.group(2)) * (10 ** -dec_places)
                    else:
                        esd = float(match.group(2))
                    return val, esd
                try:
                    return float(val_str), None
                except (ValueError, TypeError):
                    return None, None
            
            label = get_val('label')
            if label:
                type_raw = get_val('type')
                elem = None
                if type_raw:
                    elem = re.sub(r'[0-9+-]+', '', type_raw)
                    elem = elem.capitalize() if len(elem) > 1 else elem.upper()
                
                occ, _ = parse_numeric(get_val('occupancy'))
                fx, _ = parse_numeric(get_val('fract_x'))
                fy, _ = parse_numeric(get_val('fract_y'))
                fz, _ = parse_numeric(get_val('fract_z'))
                wyckoff = get_val('wyckoff')
                mult_str = get_val('multiplicity')
                mult = int(mult_str) if mult_str and mult_str.isdigit() else None
                
                result[label] = {
                    'element': elem,
                    'occupancy': occ if occ is not None else 1.0,
                    'wyckoff': wyckoff,
                    'multiplicity': mult,
                    'fract_x': fx, 'fract_y': fy, 'fract_z': fz,
                }
    
    return result


# ============================================================================
# CONFIG FILE SUPPORT
# ============================================================================

def _coerce_oxidation_state(v):
    """
    Parse an oxidation state from a config, preserving fractional values.

    v1.8.3 (B4): the previous int(v) silently truncated, so a config entry of
    Mn: 3.5 became Mn: 3 and every downstream fractional-valence code path was
    bypassed. Integers are returned as int so existing formatting is unchanged.
    """
    f = float(v)
    return int(f) if f == int(f) else f


def load_oxidation_states_from_config(config_path=None, config_dict=None):
    """
    Load oxidation states from config file or dictionary.
    """
    if config_dict is not None:
        if not isinstance(config_dict, dict):
            print("Error: config_dict must be a dictionary")
            return None
        
        try:
            # v1.8.3 (B4): keep fractional oxidation states. Casting
            # to int defeated the fractional-valence support
            # whenever a config was supplied.
            validated = {str(k): _coerce_oxidation_state(v)
                         for k, v in config_dict.items()}
            print(f"Loaded oxidation states from provided dictionary:")
            for elem in sorted(validated.keys()):
                print(f"    {elem}: {validated[elem]:+g}")
            return validated
        except (ValueError, TypeError) as e:
            print(f"Error validating config_dict: {e}")
            return None
    
    if config_path is not None:
        if not os.path.exists(config_path):
            print(f"Config file not found: {config_path}")
            return None
        
        try:
            with open(config_path, 'r') as f:
                data = json.load(f)
            
            # v1.8.3 (B4): keep fractional oxidation states. Casting
            # to int defeated the fractional-valence support
            # whenever a config was supplied.
            validated = {str(k): _coerce_oxidation_state(v)
                         for k, v in data.items()}
            print(f"Loaded oxidation states from {config_path}:")
            for elem in sorted(validated.keys()):
                print(f"    {elem}: {validated[elem]:+g}")
            return validated
        except json.JSONDecodeError as e:
            print(f"Error parsing JSON in {config_path}: {e}")
            return None
        except (ValueError, TypeError) as e:
            print(f"Error validating oxidation states in {config_path}: {e}")
            return None
    
    return None


def auto_detect_config_file(directory):
    """Automatically search for config.json in the target directory."""
    config_path = os.path.join(directory, "config.json")
    if os.path.exists(config_path):
        print(f"Found config.json in {directory}")
        return config_path
    return None


# ============================================================================
# 3D VISUALISATION OF PROBLEMATIC SITES
# ============================================================================
# v1.8.4 rewrite. The previous version loaded the whole CIF, replicated it
# 2x2x2 and zoomed to the lot, so the one site you actually wanted to look at
# was an anonymous sphere among a hundred identical ones, with no bonds drawn
# to it and no way to tell which it was. It also coloured the central cation
# red and oxygen blue, which inverts the convention every crystallographer
# reads by reflex.
#
# This version builds the coordination polyhedron explicitly: the central atom,
# its ligands, one cylinder per bond, and the distance written on each bond.
# Nothing else is drawn, because nothing else is being discussed.

# CPK-ish, so the picture reads the way a chemist expects
VIZ_ELEMENT_COLOURS = {
    'O': '#ff2200', 'F': '#90e050', 'Cl': '#1ff01f', 'S': '#ffff30',
    'N': '#3050f8', 'Na': '#ab5cf2', 'Li': '#cc80ff', 'K': '#8f40d4',
    'Mg': '#8aff00', 'Ca': '#3dff00', 'Cr': '#8a99c7', 'Mn': '#9c7ac7',
    'Fe': '#e06633', 'Co': '#f090a0', 'Ni': '#50d050', 'Cu': '#c88033',
    'Zn': '#7d80b0', 'Ti': '#bfc2c7', 'V': '#a6a6ab', 'Al': '#bfa6a6',
    'Sb': '#9e63b5', 'Nb': '#73c2c9', 'Ru': '#248f8f', 'Sr': '#00ff00',
    'Ba': '#00c900', 'B': '#ffb5b5', 'Si': '#f0c8a0', 'P': '#ff8000',
}
VIZ_DEFAULT_COLOUR = '#c0c0c0'

# A cation-anion contact below this fraction of the sum of the ionic radii is
# taken as an error in the deposited coordinates rather than as chemistry. The
# 15% margin allows for normal bond-length variation and thermal motion while
# still catching genuine overlaps. Same value the batch post-processor uses.
IMPLAUSIBLE_CONTACT_FRACTION = 0.85

# Second, independent geometry test, expressed in the tool's own terms.
#
# The Shannon test above needs one threshold per structural role: sodium's
# shortest contacts have a 5th percentile of 0.763 while framework cations sit
# at 0.890, so a single cut either misses bad transition-metal sites or
# condemns good alkali ones. Hardcoding an "alkali vs framework" split would
# work for layered oxides and mean nothing in a phosphate.
#
# R0 and b already encode both the size and the SOFTNESS of a bond, which is
# what the radii sum omits. The distance at which a cation would reach its
# expected valence at its observed coordination is
#     d_ideal = R0 - b*ln(V/N)
# and d_observed/d_ideal needs no element classes at all. On the reference set
# the 5th percentiles of the two populations agree to 2.6% on this measure
# against 14% on the radii ratio, so one threshold serves both.
#
# Kept ALONGSIDE the Shannon test rather than replacing it. This measure is
# circular in a way the other is not: it uses the bond valence parameters to
# judge whether the geometry is consistent with the bond valence parameters.
# That is fine for catching a misplaced atom and weaker as independent
# evidence, so having one test that depends on the parameter set and one that
# does not is worth the extra column.
IMPLAUSIBLE_BVS_DISTANCE_FRACTION = 0.90


# =============================================================================
# TOLERANT COMPARISON
# =============================================================================
# Occupancies, valences and the thresholds tested against them are all drawn
# from the same small set of round decimals, so a computed value landing
# exactly on a threshold is common rather than rare. On the 142-structure
# reference set: ten sites have occupancy exactly 0.90, four have a valence
# spread of exactly 0.30, and 98 of 142 structures have a charge-balance error
# that is an exact multiple of 0.01.
#
# A bare > or < then decides the outcome on the last bit of a float. The two
# structures that exposed this both balance to 0.01, but summed in the order
# their formulae are written one gives 0.010000000000000675 and the other
# 0.009999999999999787, so they fell on opposite sides of `> 0.01` and were
# flagged differently for no chemical reason.
#
# These make a tie resolve the same way every time. The epsilon is far below
# any physically meaningful difference and far above float noise.

COMPARISON_EPS = 1e-9

# A charge-balance error below this is taken as rounding in the published
# formula rather than a real imbalance. Na0.67Ni0.33Ti0.67O2 is
# Na(2/3)Ni(1/3)Ti(2/3)O2 and balances exactly, but as quoted it computes to
# 4.0100. On the reference set the error is bimodal - 131 structures below
# 0.041, eleven above 0.067, nothing between - so 0.05 sits in the gap.
CHARGE_BALANCE_TOLERANCE = 0.05


def gt(value, threshold, eps=COMPARISON_EPS):
    """value > threshold, with a tie counting as not greater."""
    return (value - threshold) > eps


def lt(value, threshold, eps=COMPARISON_EPS):
    """value < threshold, with a tie counting as not less."""
    return (threshold - value) > eps


def ge(value, threshold, eps=COMPARISON_EPS):
    """value >= threshold, with a tie counting as satisfying it."""
    return (value - threshold) > -eps


def le(value, threshold, eps=COMPARISON_EPS):
    """value <= threshold, with a tie counting as satisfying it."""
    return (threshold - value) > -eps
VIZ_CENTRAL_HALO = '#ffd700'      # gold ring so the central atom is unmistakable


def _viz_local_environment(cif_path, element, site_label, rmax=4.2, dedup_tol=0.02):
    """
    Cartesian coordinates of one site and the anions around it.

    Returns (centre_xyz, [(element, xyz, distance), ...]) or (None, []).
    Positions come from a symmetry expansion of the asymmetric unit, the same
    way the bond valence sum gets them, so the picture and the number agree.
    """
    try:
        import numpy as _np
        st = load_structure_for_viz(cif_path)
        if st is None or st.spacegroup is None:
            return None, []

        target = None
        for s in st.sites:
            if s.label == site_label or (target is None and s.element.name == element):
                target = s
                if s.label == site_label:
                    break
        if target is None:
            return None, []

        pts = []
        _rng = range(-image_range(st.cell, rmax), image_range(st.cell, rmax) + 1)
        for s in st.sites:
            for op in st.spacegroup.operations():
                # v2.0.35: wrapped, so the picture shows the same neighbours
                # the number is computed from.
                f = wrap_into_cell(op.apply_to_xyz(
                    [s.fract.x, s.fract.y, s.fract.z]))
                for i in _rng:
                    for j in _rng:
                        for k in _rng:
                            p = st.cell.orthogonalize(
                                gemmi.Fractional(f[0] + i, f[1] + j, f[2] + k))
                            pts.append((s.element.name, p.x, p.y, p.z))

        o = site_centre(st.cell, target)
        c = _np.array([o.x, o.y, o.z])
        P = _np.array([[p[1], p[2], p[3]] for p in pts])
        els = [p[0] for p in pts]
        d = _np.linalg.norm(P - c, axis=1)
        order = _np.argsort(d)

        ligands, kept = [], []
        for idx in order:
            if d[idx] <= 0.01 or d[idx] > rmax:
                continue
            if els[idx] not in ALWAYS_ANION and els[idx] not in AMPHOTERIC_ANION:
                continue
            if any(_np.linalg.norm(P[idx] - k) <= dedup_tol for k in kept):
                continue
            kept.append(P[idx])
            ligands.append((els[idx], P[idx], float(d[idx])))
        return c, ligands
    except Exception:
        return None, []


def load_structure_for_viz(cif_path):
    """gemmi SmallStructure from a CIF, reusing Eir's cleaning."""
    try:
        import tempfile as _tf
        cleaned = clean_cif_for_gemmi(cif_path)
        if cleaned is None:
            return None
        with _tf.NamedTemporaryFile('w', suffix='.cif', delete=False,
                                    encoding='utf-8') as t:
            t.write(cleaned)
            tp = t.name
        try:
            st = gemmi.make_small_structure_from_block(
                gemmi.cif.read(tp).sole_block())
        finally:
            os.unlink(tp)
        if st.spacegroup is None:
            m = (re.search(r'_space_group_IT_number\s+(\d+)', cleaned) or
                 re.search(r'_symmetry_Int_Tables_number\s+(\d+)', cleaned))
            if m:
                st.spacegroup = gemmi.find_spacegroup_by_number(int(m.group(1)))
        return st
    except Exception:
        return None

# ============================================================================
# ANION-ANION CONTACT SCREEN
# ============================================================================
# The two existing screens both look outward from a cation. Neither can see a
# structure whose ANIONS are too close to each other, and on the reference set
# seven structures fail on that alone: 9992, 19652, 147267, 175658, 175668,
# 203321 and 203322, with a mean GII near 1.0 and no cation-based warning.
#
# This is the oldest test in the book. Pauling's first rule is sphere packing:
# for a regular octahedron the O-O edge is sqrt(2) times the M-O distance, so
# oxygens 2.2 A apart have their electron clouds 0.6 A inside one another. Real
# oxides do compress below the 2.80 A hard-sphere contact, routinely to 2.5 or
# 2.6 A in edge-sharing frameworks, but 2.35 A is outside anything observed.
#
# It uses no bond valence parameters and no ionic radii for the cation, so it
# is independent of the quantities it is being used to validate.

ANION_ANION_MIN = 2.35        # A, below this the contact is not credible

# v2.0.14: WHAT THIS FLOOR DOES NOT COVER, stated because it was silent.
#
# 2.35 A was measured on perovskites, pyrochlores and spinels, all oxides.
# Run against the chalcogenide sets it is inert: across 505 sulfide, selenide
# and telluride spinels the shortest anion-anion contact is 2.469 A, so G2
# never fires on any of them and the anion sublattice of half the spinel work
# goes unscreened. The measured minima are S-S 2.998, Se-Se 2.469, Te-Te
# 2.517 A, first percentiles 3.002, 2.586, 2.524 - the low tails there are
# candidates for the gate rather than evidence about the floor, so the
# non-oxide values cannot be set from these numbers alone. They need the
# screened population, the same way the oxide value was set. Until that run
# exists the floor stays oxide-only and this comment says so.

# The search window for anion_anion_contacts, in angstroms.
#
# The default of 4.0 A is an oxide-scaled number and was never stated as one.
# Ten of 505 chalcogenide spinels have no contact of either kind inside it and
# returned (None, None); both packing gates read that as nothing to test and
# skipped, so the entry reported as screened when it was not. A further 24
# selenides had an anion contact inside 4.0 A but no cation contact, so G5
# alone skipped. Widened once, on demand, all of them resolve, with
# anion-anion minima out to 4.586 A. 6.5 A clears the largest observed
# minimum with room, and is only ever reached by the structures that need it.
ANION_CONTACT_RMAX_WIDE = 6.5

# The summation cut-off for bond valence, in valence units, applied at BOTH
# ends of every bond.
#
# s = exp((R0 - d)/b) is a property of the bond, not of the end you view it
# from, so a contact admitted to the cation sum must be admitted to the anion
# sum. Eir previously used gap analysis for cations and 0.04 v.u. for anions,
# which counted bonds in 0.02 <= s < 0.04 at one end only. That breaks the
# premise of the cation-anion comparison in the summary, which is that a
# discrepancy cancelling at the shared oxygen is a property of the parameters
# rather than of the structure.
#
# DIRECTION: sourced. Gagne & Hawthorne (2015), Acta Cryst B71, 562-578, sec 4,
# state that the longer bonds should be included when using the parameters
# derived in that work, having tested both practices and found inclusion gives
# better sums. They specify this for elements of periods 4-6 and note it is
# typically not the transition metals, which is the perovskite A site and not
# the B site. Gap analysis excludes those bonds, so every A-site sum Eir
# produced before v2.0.3 used these parameters against their authors' stated
# instruction.
#
# VALUE: a reading of that direction, not a quantity from the source. G&H give
# no numeric cut-off; they judged each polyhedron and discarded the ambiguous
# ones (their selection criterion 8), which a tool cannot reproduce. Measured
# on 830 clean ICSD perovskites, this value is the loosest cut that leaves the
# octahedral B site intact at CN 6.0. The B site is the control: it has no
# shell ambiguity, so any cut that moves it is wrong whatever it does
# elsewhere. 0.01 admits a seventh B-site bond; 0.04 and above truncate the A
# site. On 429 pyrochlores nothing moves under any cut-off between 0.01 and
# 0.08, because neither pyrochlore site is ambiguous, so the choice costs
# nothing where the structure is unambiguous and corrects the sum where it is
# not.
#
# Equivalent distance: s >= cut  <=>  d <= R0 + b*ln(1/cut). At b = 0.37 that
# is R0 + 1.447 A, an ABSOLUTE distance per ion pair, not a multiple of the
# shortest bond.
BV_SUM_CUTOFF = 0.02


# Cut-off as a function of Lewis acidity. NOT YET CANONICAL: exported beside
# the fixed-cut-off result so the change can be measured before it moves a
# verdict, the same staging as 4a/4b.
#
# A fixed s puts the boundary at R0 + b*ln(1/s), and since R0 and b vary little
# across the table that is the same ABSOLUTE distance for every cation: 3.1 to
# 3.6 A whether the ion is Li(1+) or S(6+). BV_SUM_CUTOFF = 0.02 survived the
# perovskites and the pyrochlores because neither structure type has an anion
# between the first shell and 3.2 A, not because it was right. Spinel does, and
# the same constant gave Li(1+) coordination numbers of 8, 10, 14 and 16 on 312
# of 323 sites with cn_gap_shell reading 4 or 6 beside them, which put 271 Li
# sites through the bond-valence distance screen and produced seven lithium
# compositions flagged at 100%.
#
# Fitted over 147 configurations with n >= 30 in Gagne's bond-length data,
# regressing s at the LONGEST observed bond on L = valence / CN:
#
#     s_cut = 0.4167 * L^1.391        R^2 = 0.731 (log-log)
#
#     L band     n   measured median   fitted
#     <0.20     31        0.0189       0.0196
#     0.20-0.30 21        0.0527       0.0606
#     0.30-0.40 22        0.1090       0.0904
#     0.40-0.60 23        0.1867       0.1589
#     0.60-0.90 24        0.2443       0.2793
#     0.90-1.40 16        0.7392       0.4167
#     >1.40     10        1.2347       0.7323
#
# It underfits above L ~ 0.9 and that is harmless: those cations have
# unambiguous shells and the boundary never binds. The band that matters,
# L < 0.3, fits to within 15%. Note that 0.0189 at L < 0.2 is where the fixed
# 0.02 came from, so the constant was right for the ions it was calibrated on
# and wrong for everything else.
BV_CUT_A = 0.4167
BV_CUT_N = 1.391
BV_CUT_MIN, BV_CUT_MAX = 0.01, 0.60


def bv_cutoff_for(valence, cn):
    """The summation cut-off this ion configuration implies."""
    try:
        v, c = abs(float(valence)), float(cn)
    except (TypeError, ValueError):
        return BV_SUM_CUTOFF
    if c <= 0 or v <= 0 or v != v or c != c:
        return BV_SUM_CUTOFF
    return min(BV_CUT_MAX, max(BV_CUT_MIN, BV_CUT_A * (v / c) ** BV_CUT_N))


def bv_shell_boundary(element, valence, cn, anion='O', r0=None, b=None,
                      db=None):
    """
    The distance at which this ion's coordination shell ends.

    MEASURED where possible. Gagne's longest observed bond for the ion
    configuration IS the boundary: it is, by construction, the furthest contact
    anyone counted as bonded in that coordination across the survey. Using it
    needs no fit and no threshold of ours.

    The Lewis-acidity fit is the fallback where the sample is thin. It is only
    a fallback: measured against fitted, Li(1+) CN 4 is 2.444 A against 2.862
    (n = 419) and Zn(2+) CN 4 is 2.076 against 2.389 (n = 227). A 0.4 A error
    in a shell boundary is a coordination number or two.

    Returns (distance, source).
    """
    db = db or db_manager
    try:
        v = int(round(float(valence)))
        c = int(round(float(cn)))
    except (TypeError, ValueError):
        return None, 'unavailable'
    if c <= 0:
        return None, 'unavailable'

    bl = db.load_bond_lengths() or {}

    hit = bl.get((element, v, anion, c))
    if hit and (hit.get('n_bonds') or 0) >= BL_MIN_SAMPLE and hit.get('max'):
        return float(hit['max']), f"measured_n{hit['n_bonds']}"

    # v2.0.8: interpolate across coordination, as expected_bond_length already
    # does. Without this every configuration measured at CN 6 and 8 but not 7,
    # and every rare-earth A site above the tabulated range, fell through to
    # the fit: 30 of 77 sites on the test batch, and the fit is the part of
    # this that is out by 0.4 A on Li and 0.3 A on Zn.
    known = sorted(k[3] for k in bl
                   if k[:3] == (element, v, anion)
                   and (bl[k].get('n_bonds') or 0) >= BL_MIN_SAMPLE
                   and bl[k].get('max'))
    if known:
        lo = max([x for x in known if x < c], default=None)
        hi = min([x for x in known if x > c], default=None)
        if lo is not None and hi is not None:
            a = bl[(element, v, anion, lo)]['max']
            z = bl[(element, v, anion, hi)]['max']
            f = (c - lo) / (hi - lo)
            return float(a + f * (z - a)), f'measured_interp_CN{lo}_{hi}'
        near = min(known, key=lambda x: abs(x - c))
        # Extrapolating an extreme is worse than interpolating one, so this is
        # named differently and should be read with the same caution as tier 3
        # in expected_bond_length.
        return float(bl[(element, v, anion, near)]['max']), \
            f'measured_extrap_CN{near}'

    if r0 is None or not b:
        return None, 'unavailable'
    cut = bv_cutoff_for(v, c)
    return r0 + b * math.log(1.0 / cut), 'lewis_fit'


def bv_shell_cn_adaptive(sorted_distances, r0, b, valence, cn_seed,
                         element=None, anion='O', max_iter=4):
    """
    Coordination number from the ion's own shell boundary.

    The boundary depends on CN and CN depends on the boundary, so this
    iterates from the gap shell, which Eir already has and which is right in
    magnitude even where it is wrong in detail.

    The iteration is clamped so it can only TIGHTEN. Left free it runs away:
    a boundary loose enough to admit the second shell raises CN, which lowers
    Lewis acidity, which loosens the boundary further. On a synthetic Li 16d
    site that took the count to 18. The failure mode being fixed here is
    over-counting, so the safe direction is the only one allowed.
    """
    ds = sorted(float(d) for d in sorted_distances if d and d > 0)
    ev = {'cn_method_adaptive': 'bond_valence_shell_adaptive',
          'bv_boundary_adaptive': None, 'bv_boundary_source': None,
          'bv_cut_iterations': 0}
    if not ds or r0 is None or not b:
        ev['cn_method_adaptive'] = 'unavailable'
        return 0, ev

    try:
        cn = max(1, int(cn_seed))
    except (TypeError, ValueError):
        cn = SHIFT_SHELL_SIZE

    d_cap = None
    for it in range(max_iter):
        d_max, src = bv_shell_boundary(element, valence, cn, anion, r0, b)
        if d_max is None:
            ev['cn_method_adaptive'] = 'unavailable'
            return 0, ev
        # Clamp: never loosen beyond the tightest boundary seen so far.
        d_cap = d_max if d_cap is None else min(d_cap, d_max)
        new = sum(1 for d in ds if d <= d_cap)
        ev['bv_boundary_adaptive'] = round(d_cap, 4)
        ev['bv_boundary_source'] = src
        ev['bv_cut_iterations'] = it + 1
        if new == cn or new == 0:
            break
        cn = new
    return int(cn), ev


def bv_shell_cn(sorted_distances, r0, b, cutoff=BV_SUM_CUTOFF):
    """
    Coordination number by bond-valence contribution.

    Every neighbour whose contribution reaches `cutoff` is in the shell, taken
    in ascending distance order so the result is a shell rather than a set.

    Unlike gap analysis this makes no assumption that the polyhedron is
    compact, which is why it behaves on a tilted perovskite A site where the
    gap cut lands inside the coordination sphere. Unlike a multiple of the
    shortest bond it does not scale with compression: the boundary is
    R0 + b*ln(1/cutoff), fixed for the ion pair.

    Returns (cn, evidence). cn is 0 when no neighbour reaches the cut-off,
    which is a failure to be reported, not a shell of size zero.
    """
    ds = sorted(float(d) for d in sorted_distances if d and d > 0)
    ev = {'cn_method': 'bond_valence_shell',
          'bv_shell_cutoff': cutoff,
          'bv_shell_max_distance': None,
          'bv_shell_last_s': None,
          'bv_shell_next_s': None,
          # v2.0.37: declared here with the rest, so a caller can read the key
          # on every site rather than only where the shell has a bond outside
          # it to compare against.
          'cn_shell_confidence': None}

    if not ds or r0 is None or not b:
        ev['cn_method'] = 'unavailable'
        return 0, ev

    d_max = r0 + b * math.log(1.0 / cutoff)
    ev['bv_shell_max_distance'] = round(d_max, 4)

    cn = 0
    for d in ds:
        if d > d_max:
            break
        cn += 1

    if cn:
        ev['bv_shell_last_s'] = round(math.exp((r0 - ds[cn - 1]) / b), 4)
    if cn < len(ds):
        # What the next bond out would have contributed. A site sitting just
        # inside the boundary is a different thing from one well clear of it,
        # and the report should be able to tell them apart.
        ev['bv_shell_next_s'] = round(math.exp((r0 - ds[cn]) / b), 4)

    # v2.0.37: and the ratio, because that is the form the two numbers are
    # actually read in. Small means the shell ends in empty space; near one
    # means the cut fell between two near-equivalent bonds and the
    # coordination number is a statement about a threshold rather than about a
    # shell. Measured over 938 perovskites: median 0.005 at CN 6 and 0.186 at
    # CN 12, against 0.724 at CN 10, where 104 of 110 sites refuse a bond
    # worth more than half the last one admitted.
    if ev['bv_shell_last_s'] and ev['bv_shell_next_s'] is not None:
        ev['cn_shell_confidence'] = round(
            ev['bv_shell_next_s'] / ev['bv_shell_last_s'], 4)

    return int(cn), ev


def econ_weighted_bvs(distances, r0, b, max_iter=25, tol=1e-9):
    """
    Bond valence summed with Hoppe's ECoN weights instead of a cut-off.

    Each neighbour contributes s_i * w_i, with w_i = exp(1 - (d_i/d_av)^6) and
    d_av the ECoN weighted mean bond length. There is no boundary, so there is
    no convention to argue about and no discontinuity as a bond crosses one.
    That is the point of it, and also its limit.

    NOT the GII, and not comparable with any published bond valence sum. G&H
    fitted R0 and b against UNWEIGHTED sums over their chosen shells, so a
    weighted sum does not satisfy the equation those parameters were fitted to.
    Quote it as a second diagnostic, never as the validation figure, and never
    against the 50.8% rock salt pass rate or anything else in the literature.

    Pass a generous neighbour list: the weights fall off as the sixth power, so
    including too much costs nothing and truncating too early defeats the
    purpose.
    """
    d = np.asarray([float(x) for x in distances if x and x > 0], float)
    if d.size == 0 or r0 is None or not b:
        return None, None

    d_av = d.min()
    for _ in range(max_iter):
        w = np.exp(1.0 - (d / d_av) ** 6)
        new = (d * w).sum() / w.sum()
        if abs(new - d_av) < tol:
            break
        d_av = new

    w = np.exp(1.0 - (d / d_av) ** 6)
    s = np.exp((r0 - d) / b)
    return float((s * w).sum()), float(w.sum())


# v2.0.44: A SHELL DOES NOT CROSS A VOID INTO CONTACTS NO SURVEY CALLS BONDS.
#
# The bond-valence boundary is R0 + b ln(1/BV_SUM_CUTOFF), an absolute
# distance per ion pair: about R0 + 1.45 A at b = 0.37. Gagne and Hawthorne
# (2015) fitted some ions with a much softer b, and for those the boundary
# reaches the second sphere: Os(5+) b = 0.485 reaches 3.77 A, Re(5+) 0.557
# reaches 4.01 A, Sb(5+) 0.475 3.75 A, U(5+) 0.660 4.59 A. On the pyrochlore
# B site the second sphere of oxygens sits at a*sqrt(x^2 + 1/32), 3.6 to
# 3.9 A, so for those ions the shell went straight through it. Every Cd2Os2O7
# and Hg2Os2O7 entry in the ICSD came out at CN 12 with a sum 0.13 v.u. above
# its own octahedron, and Cd2Re2O7 0.24 above. The six extra "bonds" are
# 3.72 A long; the longest Os(5+)-O bond in Gagne's survey is 2.04 A.
#
# apply_shell_correction (CELL 7) already repairs this where Gagne measured
# the boundary for the configuration (n >= BL_MIN_SAMPLE). Os(5+) has four
# bonds in the survey and Re(5+) three, so it never fired for them, and the
# Lewis-acidity fallback is rightly not trusted to replace a shell alone.
#
# This guard needs no fitted boundary. A contact leaves the shell only if
# BOTH hold:
#
#   1. it lies beyond a VOID: at least SHELL_VOID_RATIO times the contact
#      before it. Consecutive bonds inside a real coordination sphere do not
#      jump by half: a tilted perovskite A site runs 2.42 to 3.21 A in steps
#      of 0.1 A or less, a lone-pair Bi(3+) site 2.15 to 2.6 to 3.2 A. The
#      second sphere of a compact polyhedron does: 1.93 to 3.72 A on the
#      pyrochlore B site (x1.92), sqrt(3) in rock salt, x1.91 in fluorite.
#   2. it is longer than the longest bond Gagne records for that ion and
#      anion at ANY coordination number. This protects lone-pair ions, whose
#      long contacts can follow a void and are still bonds: Sn(2+)-O runs to
#      3.41 A in the survey and Tl(1+)-O to 4.01 A.
#
# Condition 2 is not the screen v2.0.5 rejected (OBSERVED AGAINST MEASURED,
# CELL 2). That compared each bond with the maximum at its own coordination
# number, where high-CN samples are thin, and condemned 224 perovskite A
# sites. Here the maximum is over every coordination number, which can only
# make it larger, and it is consulted only behind a void, which the
# perovskite A site does not have.
#
# No reference, no guard: an ion with no measured bond lengths against that
# anion keeps the plain bond-valence shell. The guard can only shorten a
# shell, never lengthen one.
SHELL_VOID_RATIO = 1.5

_gagne_longest_cache = {}


def gagne_longest_bond(element, valence, anion='O', db=None):
    """
    The longest bond Gagne's survey records for this ion against this anion,
    at any coordination number, and the number of bonds behind the survey.

    A fractional valence reads both neighbouring integers and keeps the
    larger, the generous direction for a value whose job is to PROTECT a
    contact. Returns (distance, n_bonds), or (None, 0) with no data.
    """
    try:
        v = abs(float(valence))
    except (TypeError, ValueError):
        return None, 0
    if v != v:
        return None, 0
    vals = tuple(sorted({int(math.floor(v)), int(math.ceil(v))}))
    key = (element, vals, anion, id(db) if db is not None else None)
    if key in _gagne_longest_cache:
        return _gagne_longest_cache[key]
    db = db or db_manager
    bl = db.load_bond_lengths() or {}
    best, n = None, 0
    for k, rec in bl.items():
        if (k[0] == element and k[1] in vals and k[2] == anion
                and rec.get('max')):
            n += int(rec.get('n_bonds') or 0)
            if best is None or float(rec['max']) > best:
                best = float(rec['max'])
    _gagne_longest_cache[key] = (best, n)
    return best, n


def shell_void_cut(sorted_distances, element, valence, anion='O',
                   ratio=None):
    """
    Where a bond-valence shell crosses a void into the second sphere.

    Takes the shell's own distances. Returns (k, evidence): k is the number
    of contacts to keep, or None when the shell stands. The two conditions
    are set out at SHELL_VOID_RATIO.
    """
    ratio = SHELL_VOID_RATIO if ratio is None else ratio
    ds = sorted(float(d) for d in sorted_distances if d and d > 0)
    d_ref, n_ref = gagne_longest_bond(element, valence, anion)
    ev = {'shell_void_reference_max': d_ref,
          'shell_void_reference_n': n_ref,
          'shell_void_ratio': None, 'shell_void_limit': None,
          'shell_void_next': None}
    if d_ref is None or len(ds) < 2:
        return None, ev
    for k in range(1, len(ds)):
        if ds[k] >= ratio * ds[k - 1] and ds[k] > d_ref:
            ev.update(shell_void_ratio=round(ds[k] / ds[k - 1], 4),
                      shell_void_limit=round(ds[k - 1], 4),
                      shell_void_next=round(ds[k], 4))
            return k, ev
    return None, ev


def VALIDATE_SHELL(verbose=True):
    """
    The shell rule against cases with known answers.

    Test 1 is the control that decided the cut-off and must not be quietly
    weakened: an octahedron has one shell however you cut it.
    """
    results = []

    def report(name, ok, detail=''):
        results.append(ok)
        if verbose:
            print(f"  {'PASS' if ok else 'FAIL'}  {name}")
            if detail:
                print(f"        {detail}")

    # 1. A regular octahedron must give CN 6 and nothing else.
    r0, b = 1.759, 0.37                       # Fe3+-O
    oct_d = [1.98] * 6 + [3.42] * 8           # 6 bonds, then the A cations
    cn, ev = bv_shell_cn(oct_d, r0, b)
    report('1. regular octahedron returns CN 6', cn == 6,
           f'boundary {ev["bv_shell_max_distance"]} A, got CN {cn}')

    # 2. A tilted A site: 8 short and 4 long, all of which G&H say to include.
    r0, b = 2.172, 0.37                       # La3+-O
    a_site = [2.42, 2.44, 2.51, 2.55, 2.61, 2.67, 2.72, 2.78,
              3.02, 3.09, 3.15, 3.21, 4.10]
    cn, ev = bv_shell_cn(a_site, r0, b)
    report('2. tilted A site keeps the long bonds', cn == 12,
           f'boundary {ev["bv_shell_max_distance"]} A, got CN {cn}')

    # 3. The boundary is absolute, not relative. Compressing every bond by 5%
    #    must NOT change which bonds are in the shell in the same way a
    #    multiple-of-shortest rule would.
    cn_c, _ = bv_shell_cn([d * 0.95 for d in a_site], r0, b)
    report('3. shell does not scale with compression', cn_c >= cn,
           f'{cn} bonds at nominal, {cn_c} at 0.95x')

    # 4. No neighbour inside the boundary is CN 0, reported, not defaulted.
    cn_z, ev_z = bv_shell_cn([4.5, 4.8], r0, b)
    report('4. nothing in range returns CN 0', cn_z == 0)

    # 5. Missing parameters are declared, not silently treated as a pass.
    _, ev_n = bv_shell_cn([2.0, 2.1], None, 0.37)
    report('5. absent parameters report cn_method unavailable',
           ev_n['cn_method'] == 'unavailable')

    # 6. The ECoN-weighted sum is close to, and below, the unweighted one on a
    #    regular polyhedron, where the weights are all near unity.
    r0, b = 1.759, 0.37
    tot, econ = econ_weighted_bvs([1.98] * 6, r0, b)
    plain = 6 * math.exp((r0 - 1.98) / 0.37)
    report('6. ECoN-weighted sum tracks the plain sum when regular',
           tot is not None and abs(tot - plain) / plain < 0.02
           and abs(econ - 6.0) < 0.05,
           f'weighted {tot:.3f} against plain {plain:.3f}, ECoN {econ:.2f}')

    # 7 to 10. v2.0.44, the void guard. Self-calibrating: each case reads the
    #    survey maximum Eir will use and builds the shell around it.
    _os_ref, _ = gagne_longest_bond('Os', 5, 'O')
    _sn_ref, _ = gagne_longest_bond('Sn', 2, 'O')
    if _os_ref is None or _sn_ref is None:
        report('7-10. void guard (no bond-length data loaded)', False,
               'gagne_bond_lengths.json is needed for these cases')
    else:
        # 7. A pyrochlore B site: six bonds, then the second sphere at 1.92x.
        _d1 = _os_ref - 0.10
        _b_site = [_d1] * 6 + [1.92 * _d1] * 6
        _cn_bv, _ = bv_shell_cn(_b_site, 1.87, 0.485)
        _k, _ev = shell_void_cut(_b_site[:_cn_bv], 'Os', 5, 'O')
        report('7. Os(5+) shell stops at the void before the second sphere',
               _cn_bv == 12 and _k == 6,
               f'bond-valence shell {_cn_bv}, after the guard {_k}; '
               f'survey maximum {_os_ref:.3f} A')
        # 8. A lone pair: a void, but the long contacts are within the survey.
        _long = _sn_ref - 0.05
        _lp = [_long / 1.6] * 3 + [_long] * 3
        _k8, _ = shell_void_cut(_lp, 'Sn', 2, 'O')
        report('8. a lone-pair shell inside the survey maximum stands',
               _k8 is None, f'Sn(2+) long contacts at {_long:.3f} A, got {_k8}')
        # 9. The tilted A site of test 2 has no void and must not move.
        _k9, _ = shell_void_cut(a_site[:12], 'La', 3, 'O')
        report('9. the tilted perovskite A site has no void', _k9 is None,
               f'got {_k9}')
        # 10. No reference data, no guard.
        _k10, _ev10 = shell_void_cut([1.9] * 6 + [3.7] * 6, 'Xx', 5, 'O')
        report('10. without measured bond lengths the shell stands',
               _k10 is None and _ev10['shell_void_reference_max'] is None)

    ok = all(results)
    print(f"\n  {'ALL SHELL TESTS PASSED' if ok else 'SOMETHING FAILED'}"
          f"  ({sum(results)}/{len(results)})")
    return ok
# The cation sublattice floor, set from measurement.
#
# cation_cation_min has been computed since v2.0.2 and nothing compared it
# against anything. Set from the measured distributions rather than by
# analogy with the anion floor: cations vary far more than anions, and
# edge- and face-sharing polyhedra put them legitimately close - 2.96 A
# for Ti-Ti in rutile, 2.65 A for Al-Al in corundum.
#
# Shortest cation-cation contact, structures passing every other screen:
#
#     family        n     min    1st pct   median
#     perovskite  938   1.912     2.787     3.148
#     pyrochlore  472   3.216     3.405     3.627
#     spinel     1877   1.648     2.363     2.915
#
# 2.40 sits below the 1st percentile of all three while catching 59
# structures, 19 of which no other screen sees - including ICSD 133663
# (NdNiO3, Nd-Ni 1.912 A) and 13793 (SrSnO3, Sn-Sr 2.019 A), both of which
# sat in the triage's UNEXPLAINED bucket. 2.6 adds two; 2.0 loses the
# spinel cases.
CATION_CATION_MIN = 2.40      # A, measured; see above

# v2.0.46: TWO MONOVALENT CATIONS MAY COME CLOSER.
#
# The floor above was measured on perovskites, pyrochlores and spinels, which
# hold no lithium-rich phase, and it expunged Li2O and Li3N: 13 of 16 ICSD
# Li2O entries and 30 of 34 Li3N on G5, for Li-Li contacts of 2.31 and 2.10 A.
#
# A floor scaled by size does not separate them from the faults. Against the
# sum of the two Shannon radii (CN 6), the Li-Li contacts of Li3N sit at 1.38
# to 1.45, inside the range of the perovskites G5 condemns at 1.91 to 2.16 A
# (1.06 to 1.40). What separates them is charge, as Pauling's third rule says
# it should. Of every cation-cation contact below 2.40 A in the corpora and
# the 870 ICSD entries, the only ones in otherwise sound structures are
# between two Li(+): Li3N 2.10 to 2.20 A, Li2CO3 2.22 A, Li2O 2.31 to 2.39 A.
# Below 2.40 A, every contact involving a cation of higher charge is one of
# the known faults: shifted perovskites, pyrochlores with Bi and Ru 0.13 to
# 0.16 A apart, spinels with over-full neighbouring sites.
#
# A pair of cations of charge one or less (an alkali metal counts whatever
# the file states) is therefore held to MONOVALENT_PAIR_MIN, and any pair
# with a cation of higher or unknown charge to CATION_CATION_MIN. Still
# caught: the over-full Li positions of ICSD 164285 to 164287, 1.83 A apart,
# and the Li2O model 216717 at 1.03 A. The heavier monovalent ions (Cu, Ag,
# Hg, Tl) never come within 2.47 A of each other in these sets, so for them
# the lower floor has been measured against nothing, and errs towards
# passing.
MONOVALENT_PAIR_MIN = 2.00    # A, measured; see above
ALWAYS_MONOVALENT = frozenset({'Li', 'Na', 'K', 'Rb', 'Cs'})


def cation_floor(el1, v1, el2, v2):
    """The packing floor for one pair of cations; see MONOVALENT_PAIR_MIN.
    v1 and v2 are the stated charges, or None."""
    def _mono(el, v):
        if el in ALWAYS_MONOVALENT:
            return True
        try:
            return 0.0 < abs(float(v)) <= 1.0 + 1e-6
        except (TypeError, ValueError):
            return False
    return (MONOVALENT_PAIR_MIN if _mono(el1, v1) and _mono(el2, v2)
            else CATION_CATION_MIN)

# v2.0.15: WHAT THIS FLOOR DOES NOT APPLY TO.
#
# All three families above are hydrogen-free, and the floor is meaningless for
# hydrogen. The H-H distance inside a single water molecule is 1.51 A; two
# hydroxyls in a hydrogen-bonded chain sit closer still. Run against 101 ICSD
# borosulfates the floor condemned 31 of them on an H contact - 20 H-H, 6 H-S,
# 5 H-N - and 12 on anything else. A proton is not a packing sphere and its
# position in an X-ray refinement is usually placed rather than found.
#
# H is therefore excluded from the cation-cation measurement in
# anion_anion_contacts, which means cation_cation_min never carries an H
# contact and this floor never judges one. Nothing in the three reference
# families changes: none of them contains hydrogen.
#
# The cost is stated: a genuinely impossible H position is now invisible to
# G5. It was never visible to a floor measured without hydrogen in it.
CATION_FLOOR_EXCLUDED_ELEMENTS = frozenset({'H', 'D'})
SPLIT_SITE_MAX = 1.20         # A, closer than this with occupancies summing to
                              # <= 1 means one atom written as two positions

# v2.0.46: ALTERNATIVE POSITIONS, AT ANY DISTANCE BELOW THE FLOOR.
#
# The rule above stopped at SPLIT_SITE_MAX, so two partly occupied positions
# further apart were counted as a contact even where the model never fills
# both. The two sodium positions of a P2-type layered oxide (2b and 2d) sit
# a/sqrt(3), about 1.70 A, apart at occupancies near 0.2 and 0.45: ICSD
# 253190, 253192 and 261554 came out EXPUNGE on G5 for a contact no sodium
# layer contains. ICSD 291603, a rock-salt-derived CrO2 with Cr shared
# between octahedral (0.667) and tetrahedral (0.167) interstices 1.77 A
# apart, the same.
#
# What decides it is the occupancy sum, not the distance. Two sets of
# positions can be filled without ever filling a close pair only if their
# occupancies sum to no more than one; above that, some close pairs must be
# filled together whatever the ordering, so the model implies the contact
# and the gate stands. The rule therefore runs to the packing floor. Above
# the floor no gate reads the contact, and the reported minimum is unchanged.
#
# A position refined to zero occupancy holds no atom and is left out of both
# packing scans altogether (Richmond's anion-disorder pyrochlore models put O
# on the empty 8b site at zero occupancy in 11 entries).
ALTERNATIVE_OCC_SUM_MAX = 1.02

# v2.0.46: AND THE DEPOSITOR'S OWN UNCERTAINTIES.
#
# A fixed allowance of 0.02 expunged models that are over-full only within
# their own error bars: in La2Zr2O7 (ICSD 189344) oxygen on 8b at 0.04(2)
# beside 48f at 0.99 sums to 1.03, 1.5 standard uncertainties over one. The
# gate says the model cannot be right, and a model right within its stated
# precision is not that. So a close pair counts as alternatives when the
# excess over one is within OCC_ESD_K combined standard uncertainties, or
# within ALTERNATIVE_OCC_SUM_MAX - 1 where that is larger (no uncertainty
# given, or a fixed occupancy). The uncertainties are combined in quadrature
# for two labels and doubled for two images of one label, whose occupancy is
# one parameter.
#
# Measured on Richmond's pyrochlores: of the 18 entries on G2 whose closest
# pair sums to 1.10 or less, six lie within 3 sigma and are released (189344,
# 173796, 213453, 121049, 180491, 173792); nine are over-full by 4 to 32
# sigma and stay; 213452 sits at 3.0 sigma and stays; two give no
# uncertainty. Nothing in the spinels or fluorites changes.
OCC_ESD_K = 3.0


def _are_alternatives(s1, s2, esd=None):
    """v2.0.46. Can the model fill these two positions one at a time? Their
    occupancies sum to one or less, within ALTERNATIVE_OCC_SUM_MAX or
    OCC_ESD_K standard uncertainties of the deposited occupancies (doubled for
    two images of one label). The packing gates' rule, for any two sites."""
    import math as _m
    esd = esd or {}
    o1 = 1.0 if getattr(s1, 'occ', None) is None else float(s1.occ)
    o2 = 1.0 if getattr(s2, 'occ', None) is None else float(s2.occ)
    g1, g2 = esd.get(s1.label, 0.0), esd.get(s2.label, 0.0)
    sig = 2.0 * g1 if s1.label == s2.label else _m.hypot(g1, g2)
    allow = max(ALTERNATIVE_OCC_SUM_MAX - 1.0, OCC_ESD_K * sig)
    return (o1 + o2 - 1.0) <= allow + 1e-9


def _occupancy_esds(cif_path):
    """{label: standard uncertainty of its occupancy}, 0.0 where none is
    given ("1." or "0.41583"). Read from the CIF text, because the parsed
    structure keeps the value and drops the uncertainty."""
    out = {}
    try:
        doc = gemmi.cif.read_file(str(cif_path))
        block = doc.sole_block() if len(doc) == 1 else doc[0]
        table = block.find(['_atom_site_label', '_atom_site_occupancy'])
    except Exception:
        return out
    for row in table:
        lab = gemmi.cif.as_string(row[0])
        m = re.match(r'^\s*[-+]?(\d*)(?:\.(\d*))?\((\d+)\)\s*$', row[1])
        if not m:
            out[lab] = 0.0
            continue
        out[lab] = int(m.group(3)) * 10.0 ** (-len(m.group(2) or ''))
    return out

# No cation-oxygen bond in any oxide is shorter than this. B-O runs to about
# 1.37 A, C-O in carbonate to 1.28, Si-O to 1.60; 1.20 leaves clearance below
# all of them. Like ANION_ANION_MIN this is a single constant with no
# element-specific input, so a contact below it is not a short bond, it is not
# a bond. The all_cations variant of ICSD 11616 produced a Dy-O contact of
# 1.181 A, from which Eir built a shell of one and reported the site as
# overbonded at 8.258 v.u.

CATION_ANION_ABSOLUTE_MIN = 1.20

# v2.0.46: A HALOGEN THE CIF STATES IS POSITIVE IS A CATION.
#
# ALWAYS_ANION was taken literally: Cl, Br and I were anions whatever the
# file said. In a perchlorate (Cl(7+)), chlorate (Cl(5+)), chlorite
# (Cl(3+)), bromate or iodate each X-O bond was then read as two anions
# 1.4-1.8 A apart: of 49 ICSD lithium, sodium and potassium chlorine
# oxysalts, 42 were expunged on G2 for their own Cl-O bonds, and the
# anion-centred sums treated Cl(7+) as an anion with nothing bonded to it.
# Bond selection follows the stated valence too (classify_bond_pair), so
# the other cations are not bonded to Cl(7+). Only a valence the CIF or the
# user states makes the change, and only for an element given one sign: a
# chloride perchlorate, with Cl at -1 and +7, needs per-site valences, and
# is left as before.
def positive_halogens(valences):
    """The species of ALWAYS_ANION that a stated positive valence makes
    cations in this structure. Keys that are site labels are ignored."""
    out = set()
    for el, v in (valences or {}).items():
        if el in ALWAYS_ANION:
            try:
                if float(v) > 0:
                    out.add(el)
            except (TypeError, ValueError):
                pass
    return out


def resolve_anions(elements, valences=None):
    """
    Which elements are acting as anions IN THIS structure.

    AMPHOTERIC_ANION exists because its members are anions in some compounds
    and cations in others: Si is an anion in Mg2Si and a cation in MgSiO3, P
    is an anion in a phosphide and a cation in a phosphate. Treating the set
    as unconditionally anionic is what the name warns against.

    anion_anion_contacts did exactly that, so in MgSiO3 every Si-O bond was
    tested against the 2.35 A anion-anion floor and failed. All eleven ICSD
    entries of that composition were flagged, and the reported
    anion_anion_min was identical to the Si-O bond length in every one, which
    is the signature: 1.7715, 1.7581, 1.7877 A.

    The rule here is the ordinary chemical one. An amphoteric element is an
    anion only if it is the most electronegative species present. Where the
    CIF states an oxidation state, that is used instead, because a depositor
    saying Si4+ settles the question.

    Returns the set of element symbols acting as anions.
    """
    els = {e for e in elements if e}
    # v2.0.46: less a halogen stated positive (positive_halogens)
    anions = {e for e in els if e in ALWAYS_ANION} - positive_halogens(valences)
    for e in els & set(AMPHOTERIC_ANION):
        v = (valences or {}).get(e)
        if v is not None:
            try:
                if float(v) < 0:
                    anions.add(e)
                continue
            except (TypeError, ValueError):
                pass
        # No stated oxidation state. v2.0.46: the rule classify_bond_pair
        # uses (acts_as_anion); it used to be 'no O, F, Cl, Br or I at all'.
        if acts_as_anion(e, els):
            anions.add(e)
    return anions


# v2.0.46: THE EDGE OF A SMALL POLYANION IS NOT A PACKING CONTACT.
#
# ANION_ANION_MIN is a statement about anions packed against one another. In
# a carbonate the O-O edge of the CO3 triangle is fixed at 2.2 A by the
# 1.28 A C-O bonds, in a nitrate at 2.16 A, and the F-F edges of BF4(-) and
# PF6(-) at 2.25 and 2.26 A: all below the floor, and none of them a contact
# between packed anions. Calcite-type carbonates (CaCO3, KCa(CO3)F) were
# expunged on G2 for their own carbonate groups, and NaPF6 or LiBF4 would
# have been. A pair of anions both bonded to the same polyanion centre, and
# closer than the floor, is therefore set aside; the shortest such edge is
# reported as polyanion_edge_min. Every other pair is tested as before, and
# an edge at or above the floor, such as the O-O edge of a silicate
# tetrahedron in a spinel, which IS part of the packing, is untouched. A
# centre counts only where the structure makes it a cation.
#
# Each centre-ligand pair carries the longest bond it allows and the
# smallest ligand-centre-ligand angle. The angle does the work: a carbonate
# crushed to an O-C-O angle of 70 degrees has an edge of 1.47 A from
# perfectly ordinary bonds, and no bond limit can see that. The bond limits
# sit above the longest bond in structures that pass every other gate.
# Measured on 870 ICSD entries and the four corpora:
#
#     pair    longest bond               smallest angle
#     C-O     1.424 A (C2O5 bridge)      110.1
#     N-O     1.397 A (Na3NO4, K3NO4)    108.6
#     Si-O    1.830 A (SiO6)              86.0
#     P-F     1.637 A                     87.8 (all NOT_ASSESSED: R3)
#     B-F     1.416 A (95th percentile)  all NOT_ASSESSED or EXPUNGE
#     Cl-O    1.70 A (95th percentile)   all NOT_ASSESSED or EXPUNGE
#
# Limits of 1.40 A for C-O and 1.35 A for N-O, tried first, expunged five
# sodium and lithium pyrocarbonates and three orthonitrates on edges of
# their own anions. Centres whose normal edges sit above the floor (SO4,
# PO4, SiO4, SeO4, AsO4) stay in: a distorted tetrahedron or an
# edge-sharing octahedron can still bring an edge below it, and the angle
# still separates that from a crushed one. The same table says which bonds
# hold a ligand to its centre (conditional_occupancy).
POLYANION_PAIRS = {            # (centre, ligand): (longest bond A, smallest angle deg)
    ('C', 'O'): (1.50, 100.0),     # CO3 120; C2O5 bridge 1.42
    ('N', 'O'): (1.50, 100.0),     # NO3 120, NO2 115, NO4 109.5 at 1.39
    ('B', 'O'): (1.60, 100.0),     # BO3 120, BO4 109.5
    ('B', 'F'): (1.50, 100.0),     # BF4 109.5
    ('Si', 'O'): (1.85, 80.0),     # SiO4 109.5, SiO6 cis 90
    ('Si', 'F'): (1.80, 80.0),     # SiF6, cis 90
    ('P', 'O'): (1.70, 95.0),      # PO4 109.5
    ('P', 'F'): (1.70, 80.0),      # PF6, cis 90
    ('S', 'O'): (1.60, 95.0),      # SO4 109.5, SO3 106
    ('Se', 'O'): (1.80, 95.0),     # SeO4 109.5, SeO3 100-105
    ('As', 'O'): (1.90, 80.0),     # AsO4 109.5, AsO6 cis 90
    ('Cl', 'O'): (1.60, 95.0),     # ClO4 109.5, ClO3 106
}
POLYANION_CENTRES = frozenset(c for c, _ in POLYANION_PAIRS)
POLYANION_BOND_MAX = max(b for b, _ in POLYANION_PAIRS.values())
# v2.0.46: the most ligands each centre takes (conditional_occupancy), and
# the most centres one ligand is bonded to (two, for the bridging O of a
# pyro-anion)
POLYANION_MOST_LIGANDS = {
    ('C', 'O'): 4, ('N', 'O'): 4, ('B', 'O'): 4, ('B', 'F'): 4,
    ('Si', 'O'): 6, ('Si', 'F'): 6, ('P', 'O'): 4, ('P', 'F'): 6,
    ('S', 'O'): 4, ('Se', 'O'): 4, ('As', 'O'): 6, ('Cl', 'O'): 4}
POLYANION_MOST_CENTRES = 2
_POLYANION_EDGE_MIN = {}    # {cif_path: shortest edge set aside}, per call
_CATION_CONTACT = {}        # {cif_path: (margin, d, label, label, floor)}, per call


def polyanion_edge(centre, ligand, b1, b2, edge):
    """Is a ligand-ligand distance `edge` the edge of a polyanion whose
    centre is bonded to both at b1 and b2? See POLYANION_PAIRS."""
    lim = POLYANION_PAIRS.get((centre, ligand))
    if lim is None or b1 > lim[0] or b2 > lim[0]:
        return False
    import math as _m
    c = (b1 * b1 + b2 * b2 - edge * edge) / (2.0 * b1 * b2)
    ang = _m.degrees(_m.acos(max(-1.0, min(1.0, c))))
    return ang >= lim[1]


def polyanion_bond(centre, ligand, d):
    """Is a centre-ligand distance d a bond inside one of the
    POLYANION_PAIRS units?"""
    lim = POLYANION_PAIRS.get((centre, ligand))
    return lim is not None and d <= lim[0]


# v2.0.46: A LIGAND THAT MOVES WITH ITS CENTRE.
#
# The bond valence sums weight each bond by the occupancy of the atom at its
# far end (v1.8.3, A8), which assumes the two ends are filled independently.
# Inside an orientationally disordered polyanion they are not: wherever the
# nitrogen of a nitrite is, its two oxygens are too. ICSD 152184, NaNO2 with
# N and O each at 0.5, summed N(3+) to 1.44 and was expunged on G7 for bonds
# it has. So for a bond inside a POLYANION_PAIRS unit the weight is the
# probability that the far end is filled GIVEN that this end is: its
# occupancy over this site's, at most one. Every other bond keeps the plain
# occupancy, because nothing says a sodium and its oxygen move together.
#
# That reading holds where each orientation has its own centre. Where the
# model spreads one centre's ligands over more positions than any single
# orientation fills, as high-temperature cubic NaClO4 does (ICSD 117375:
# Cl on 4a and 32f, O on 96j, 96k and 32f, every occupancy below 0.34),
# weighting every ligand in reach given the centre counted 47 oxygens and
# summed Cl(7+) to 53. So the conditional weights are used only where they
# give the centre no more ligands than it can take
# (POLYANION_MOST_LIGANDS), and a ligand no more centres than
# POLYANION_MOST_CENTRES; otherwise the plain occupancy stands, and the
# average it gives is the honest figure. See conditional_ligand_count.
def conditional_occupancy(p_far, p_here, centre, ligand, d):
    """Weight of a bond in an occupancy-weighted sum, seen from a site of
    occupancy p_here. centre and ligand name the pair as POLYANION_PAIRS
    does, whichever end is summing."""
    if (p_here is None or not 0.0 < p_here < 1.0 or p_far >= 1.0
            or not polyanion_bond(centre, ligand, d)):
        return p_far
    return min(1.0, p_far / p_here)


def conditional_ligand_count(bonds, p_here, centre, ligand):
    """How many partners the conditional weights give one site: bonds is
    [(far-end occupancy, distance, count)]. Only bonds inside a
    POLYANION_PAIRS unit count."""
    return sum(n * conditional_occupancy(p, p_here, centre, ligand, d)
               for p, d, n in bonds if polyanion_bond(centre, ligand, d))


def anion_anion_contacts(cif_path, rmax=4.0, dedup_tol=0.02, valences=None):
    """
    Shortest anion-anion and cation-cation contact in the structure.

    Split sites are excluded. A refinement that models one oxygen as two
    partly-occupied positions 0.18 A apart is not reporting a 0.18 A contact,
    and ICSD 194733 does exactly that. Pairs closer than SPLIT_SITE_MAX whose
    occupancies sum to no more than unity are therefore skipped.

    v2.0.46: and so are such pairs anywhere below the packing floor, which
    the model can always fill one at a time, and positions refined to zero
    occupancy. See ALTERNATIVE_OCC_SUM_MAX.

    Returns (anion_anion_min, cation_cation_min), either possibly None.

    v2.0.14: THREE FAULTS, EACH FOUND BY RUNNING THIS ON REAL FILES.

    1. THE PAIR FILTER AND THE BUCKET DISAGREED.
       same_class decided which pairs to consider from resolve_anions(),
       which reads the structure. The line that chose which bucket to put
       the distance in asked static membership of AMPHOTERIC_ANION instead.
       Wherever an amphoteric element is acting as a CATION - Si in a
       silicate, S in a sulfate, B in a borate, H in a hydrate - its
       cation-cation contacts were written to anion_anion_min and tested
       against the anion floor.

       Measured on 101 ICSD borosulfates: anion_anion_min wrong in 34,
       cation_cation_min wrong in 92. Four structures were condemned by G2
       on a distance that is not an anion-anion contact at all - ICSD 428004
       reported 1.000 A as anion packing impossible when its shortest O-O is
       2.363 A - and 35 had a cation-cation contact below the floor, down to
       0.923 A, that G5 never saw because the distance had gone into the
       other bucket. The three reference families are untouched: 0 of 27
       oxide and sulfide spinels change.

       This is the same fault resolve_anions() was written to fix. It was
       fixed at the filter and not at the bucket, which is the recurring
       shape: one idea, two implementations, drifting.

    2. rmax = 4.0 A IS AN OXIDE-SCALED WINDOW.
       Ten of 505 chalcogenide spinels have no contact of either kind inside
       4.0 A and returned (None, None). Both packing gates read that as
       'nothing to test' and skip, so the entry reports as screened when it
       was not. Re-run at 6.0 A all ten resolve, with anion-anion minima out
       to 4.586 A. The window is now widened once, on demand, and the number
       of lattice images follows the window rather than being fixed at one.

    3. except Exception: return None, None
       made a failure indistinguishable from 'nothing found', and both mean
       the gates do not fire. Narrowed. NameError, TypeError and
       AttributeError re-raise: those are defects in this function, not
       properties of the file.
    """
    import numpy as _np
    import math as _math
    _edges = []         # v2.0.46: polyanion edges set aside (POLYANION_CENTRES)
    _gov = [None]       # v2.0.46: the cation contact nearest its floor

    def _scan(st, anion_set, rmax, esd=None, sv=None):
        # v2.0.14: the image range follows the search radius. At one image a
        # 6.5 A search in a 5 A cell cannot reach the neighbour it is looking
        # for, so widening rmax alone would have been a half fix.
        # v2.0.35: the same rule as every other expansion, in one place, and
        # from the interplanar spacings rather than the edges. On this corpus
        # - all orthogonal cells - it returns exactly what the edge rule
        # returned, so the two packing gates read the same numbers. The cap of
        # 3 is gone: image_range raises instead of silently under-covering.
        rng = range(-image_range(st.cell, rmax), image_range(st.cell, rmax) + 1)

        pts = []
        for s in st.sites:
            occ = getattr(s, 'occ', 1.0)
            occ = 1.0 if occ is None else float(occ)
            if occ <= 0:
                continue                          # v2.0.46: no atom there
            for op in st.spacegroup.operations():
                f = wrap_into_cell(op.apply_to_xyz(
                    [s.fract.x, s.fract.y, s.fract.z]))
                for i in rng:
                    for j in rng:
                        for k in rng:
                            p = st.cell.orthogonalize(
                                gemmi.Fractional(f[0] + i, f[1] + j, f[2] + k))
                            pts.append((s.element.name, p.x, p.y, p.z, occ,
                                        s.label))

        esd = esd or {}
        els = [p[0] for p in pts]
        occs = _np.array([p[4] for p in pts])
        labs = [p[5] for p in pts]
        # v2.0.46: each position's stated charge, for its pair's floor
        sv = sv or {}
        _ev = valences or {}
        vals = [sv.get(p[5], _ev.get(p[0])) for p in pts]
        sigs = _np.array([esd.get(p[5], 0.0) for p in pts])
        P = _np.array([[p[1], p[2], p[3]] for p in pts])
        is_anion = _np.array([e in anion_set for e in els])
        # v2.0.46: see POLYANION_CENTRES
        is_centre = _np.array([e in POLYANION_CENTRES and e not in anion_set
                               for e in els])

        aa = cc = None
        for s in st.sites:
            el = s.element.name
            occ0 = getattr(s, 'occ', 1.0)
            occ0 = 1.0 if occ0 is None else float(occ0)
            if occ0 <= 0:
                continue                          # v2.0.46: no atom there
            sig0 = esd.get(s.label, 0.0)
            v0 = sv.get(s.label, _ev.get(el))
            o = site_centre(st.cell, s)
            p0 = _np.array([o.x, o.y, o.z])
            d = _np.linalg.norm(P - p0, axis=1)
            m = _np.where((d > dedup_tol) & (d <= rmax))[0]
            el_is_anion = el in anion_set
            _cen = (_np.where(is_centre & (d > dedup_tol)
                              & (d <= POLYANION_BOND_MAX))[0]
                    if el_is_anion else ())
            # v2.0.15: see CATION_FLOOR_EXCLUDED_ELEMENTS.
            if not el_is_anion and el in CATION_FLOOR_EXCLUDED_ELEMENTS:
                continue
            same_class = (is_anion == el_is_anion)
            for idx in m:
                if not same_class[idx]:
                    continue
                if (not el_is_anion
                        and els[idx] in CATION_FLOOR_EXCLUDED_ELEMENTS):
                    continue                      # v2.0.15: not a packing sphere
                dist = float(d[idx])
                # v2.0.46: alternatives to the floor, not to SPLIT_SITE_MAX,
                # and over-full only within the stated uncertainties
                _floor = ANION_ANION_MIN if el_is_anion else CATION_CATION_MIN
                _sig = (2.0 * sig0 if labs[idx] == s.label
                        else _math.hypot(sig0, float(sigs[idx])))
                _allow = max(ALTERNATIVE_OCC_SUM_MAX - 1.0, OCC_ESD_K * _sig)
                if (dist < max(SPLIT_SITE_MAX, _floor)
                        and (occ0 + occs[idx] - 1.0) <= _allow + 1e-9):
                    continue                      # never both filled
                # v2.0.46: an edge of this anion's own polyanion, held short
                # by the bonds to its centre, is not a packing contact
                if (el_is_anion and dist < ANION_ANION_MIN and len(_cen)
                        and els[idx] == el
                        and any(polyanion_edge(
                            els[_j], el, float(d[_j]),
                            float(_np.linalg.norm(P[_j] - P[idx])), dist)
                            for _j in _cen)):
                    _edges.append(dist)
                    continue
                # v2.0.14: the bucket now asks the same question the filter
                # asked, and asks it of the structure rather than of a list.
                if el_is_anion:
                    aa = dist if aa is None else min(aa, dist)
                else:
                    cc = dist if cc is None else min(cc, dist)
                    # v2.0.46: judged against the floor for THIS pair
                    _fl = cation_floor(el, v0, els[idx], vals[idx])
                    if _gov[0] is None or dist - _fl < _gov[0][0]:
                        _gov[0] = (dist - _fl, dist, s.label, labs[idx], _fl)
        return aa, cc

    try:
        st = load_structure_for_viz(cif_path)
        if st is None or st.spacegroup is None:
            return None, None
        # v2.0.2: decided from the structure, not from a fixed list.
        _els = {s.element.name for s in st.sites}
        _anion_set = resolve_anions(_els, valences)
        _has_anion = bool(_anion_set & _els)
        _has_cation = bool(_els - _anion_set)

        _esd = _occupancy_esds(cif_path)
        # v2.0.46: each site's own stated charge, for the pair floors
        try:
            _sv = {k: d.get('explicit_valence') for k, d in
                   (extract_per_atom_valences(cif_path) or {}).items()
                   if d.get('explicit_valence') not in (None, 0)}
        except (OSError, UnicodeDecodeError, ValueError):
            _sv = {}
        aa, cc = _scan(st, _anion_set, rmax, _esd, _sv)

        # v2.0.14: one widened retry, and only where a bucket that SHOULD
        # have a member came back empty. A structure with no cations has no
        # cation-cation contact at any radius and is not a failure.
        if ((_has_anion and aa is None) or (_has_cation and cc is None)) \
                and rmax < ANION_CONTACT_RMAX_WIDE:
            aa2, cc2 = _scan(st, _anion_set, ANION_CONTACT_RMAX_WIDE, _esd, _sv)
            aa = aa if aa is not None else aa2
            cc = cc if cc is not None else cc2
        _POLYANION_EDGE_MIN[str(cif_path)] = min(_edges) if _edges else None
        _CATION_CONTACT[str(cif_path)] = _gov[0]
        return aa, cc
    except (NameError, TypeError, AttributeError):
        # A defect in this function, not a property of the file. Fail loudly:
        # a silent (None, None) here disables BOTH packing gates for the
        # entry and nothing downstream can tell that apart from a clean pass.
        raise
    except (OSError, UnicodeDecodeError, ValueError, KeyError, IndexError,
            RuntimeError) as _e:
        _note_read_failure(cif_path, 'anion_anion_contacts', _e)
        return None, None

# v2.0.46: CARBON THAT BOND VALENCE SUMS DO NOT DESCRIBE.
#
# Carbon bonded to carbon, hydrogen or nitrogen is organic, framework or
# molecular carbon: a MOF linker, the formamidinium of a hybrid perovskite,
# the cyanide of a Prussian blue analogue, the C2 unit of a carbide. Its
# C-C, C-H and C-N bonds are covalent, there are no bond valence parameters
# that describe them, and on 212 files from other programs every such
# structure came out wrong in its own way: G7 on carbon in 19, its bonds to
# C and H not counted; G1 on C=O at 1.19 A in 3; G2 on carboxylate O-O in 6.
# UiO-66, MOF-5 and FAPbI3 all read as "the atoms cannot be where the file
# says". They are NOT_ASSESSED, and say why, before anything is computed.
# Carbon bonded only to oxygen or to metals (a carbonate, the isolated C of a
# carbide) is assessed as before, and carbon sharing a position with N (a
# carbonitride) is not bonded to it.
MOLECULAR_CARBON_PARTNERS = {'C': 1.75, 'H': 1.25, 'D': 1.25, 'N': 1.60}  # A
MOLECULAR_CARBON_NOTE = 'molecular carbon'      # eir.api reads this phrase


def molecular_carbon(cif_path):
    """The shortest contact from carbon to C, H or N close enough to be a
    covalent bond, as (carbon label, partner label, distance in A), or None.
    Positions refined to zero occupancy are left out, and so are contacts
    under 0.85 A, which are one site written twice, not a bond."""
    import itertools as _it
    import numpy as _np
    # a formula that names no carbon settles it without building anything
    try:
        with open(cif_path, encoding='utf-8', errors='ignore') as _f:
            _hint = _formula_hint(_f.read())
    except OSError:
        _hint = None
    if _hint is not None and 'C' not in _hint:
        return None
    st = load_structure_for_viz(cif_path)
    if st is None:
        return None
    sites = [s for s in st.sites
             if (1.0 if getattr(s, 'occ', None) is None else float(s.occ)) > 0]
    cs = [s for s in sites if s.element.name == 'C']
    if not cs:
        return None
    partners = [s for s in sites if s.element.name in MOLECULAR_CARBON_PARTNERS]
    rmax = max(MOLECULAR_CARBON_PARTNERS.values())
    ops = (list(st.spacegroup.operations()) if st.spacegroup is not None
           else [gemmi.Op('x,y,z')])
    rng = range(-image_range(st.cell, rmax), image_range(st.cell, rmax) + 1)
    lab, lim, pts = [], [], []
    for p in partners:
        for op in ops:
            f = wrap_into_cell(op.apply_to_xyz([p.fract.x, p.fract.y, p.fract.z]))
            for i, j, k in _it.product(rng, repeat=3):
                q = st.cell.orthogonalize(gemmi.Fractional(f[0] + i, f[1] + j, f[2] + k))
                pts.append((q.x, q.y, q.z))
                lab.append(p.label)
                lim.append(MOLECULAR_CARBON_PARTNERS[p.element.name])
    if not pts:
        return None
    P, L = _np.array(pts), _np.array(lim)
    best = None
    for c in cs:
        o = site_centre(st.cell, c)
        d = _np.linalg.norm(P - _np.array([o.x, o.y, o.z]), axis=1)
        hit = _np.where((d > 0.85) & (d <= L))[0]
        if len(hit):
            k = hit[_np.argmin(d[hit])]
            if best is None or d[k] < best[2]:
                best = (c.label, lab[k], float(d[k]))
    return best


def visualize_problematic_site_3d(cif_path, element, site_label, bonds_info,
                                  deviation, formal_charge, bvs_value,
                                  filename=None, expected_distance=None):
    """
    Draw the coordination polyhedron of one site, with every bond labelled.

    Bonds shorter than 85% of the Shannon radii sum are drawn in red, since a
    contact that short is the usual reason a site ends up here at all.
    """
    try:
        import py3Dmol
        from IPython.display import display
    except ImportError:
        print("  [3D visualisation unavailable - py3Dmol not installed]")
        return

    try:
        centre, ligands = _viz_local_environment(cif_path, element, site_label)

        file_id = ""
        if filename:
            m = re.search(r'CollCode(\d+)', filename)
            file_id = (f" in CollCode{m.group(1)}" if m
                       else f" ({filename.replace('.cif', '')})")

        try:
            fc = f"{int(formal_charge):+d}"
        except (TypeError, ValueError):
            fc = f"{formal_charge:+.2f}" if formal_charge is not None else "?"
        print(f"\n  3D VISUALISATION: {element} at site {site_label}{file_id}")
        print(f"  BVS: {bvs_value:.3f}  |  Expected: {fc}  |  "
              f"Delta: {deviation:+.3f} v.u.")

        if not ligands:
            print("  [could not rebuild the local environment for this site]")
            return

        # Show the shell Eir actually counted, not everything within the search
        # radius. bonds_info is Eir's own coordination determination, so
        # matching against it guarantees the picture and the bond valence sum
        # describe the same bonds. Anything beyond it is drawn faintly and
        # without a bond, which is what makes a truncated coordination obvious:
        # you can see the gap the site is sitting in.
        shell, outer = [], []
        if bonds_info:
            wanted = [b['distance'] for b in bonds_info
                      for _ in range(b.get('count', 1))]
            used = [False] * len(wanted)
            for lig in ligands:
                hit = next((i for i, w in enumerate(wanted)
                            if not used[i] and abs(w - lig[2]) < 0.005), None)
                if hit is None:
                    outer.append(lig)
                else:
                    used[hit] = True
                    shell.append(lig)

        if not shell:
            # v1.8.6: with nothing to match against, take the first
            # coordination shell by the relative-distance rule rather than
            # everything inside the search radius, which drew a dozen bonds
            # and made the picture as unreadable as the one this replaced.
            # Indices, not values: a ligand tuple holds a numpy array, so
            # `l not in shell` raises "truth value of an array is ambiguous".
            _cut = ligands[0][2] * 1.30
            _keep = [i for i, l in enumerate(ligands) if l[2] <= _cut]
            if not _keep:
                _keep = list(range(min(6, len(ligands))))
            shell = [ligands[i] for i in _keep]
            outer = [l for i, l in enumerate(ligands) if i not in _keep]

        outer = [o for o in outer if o[2] <= (shell[-1][2] * 2.2)][:14]

        # what a credible shortest contact would be, for colouring
        if expected_distance is None:
            rc = SHANNON_CN6_VIZ.get(element)
            ra = SHANNON_CN6_VIZ.get(ligands[0][0])
            expected_distance = (rc + ra) if (rc and ra) else None

        view = py3Dmol.view(width=680, height=520)

        ccol = VIZ_ELEMENT_COLOURS.get(element, VIZ_DEFAULT_COLOUR)
        view.addSphere({'center': {'x': float(centre[0]), 'y': float(centre[1]),
                                   'z': float(centre[2])},
                        'radius': 0.55, 'color': ccol})
        view.addSphere({'center': {'x': float(centre[0]), 'y': float(centre[1]),
                                   'z': float(centre[2])},
                        'radius': 0.62, 'color': VIZ_CENTRAL_HALO,
                        'opacity': 0.35})
        view.addLabel(f"{site_label} ({element})",
                      {'position': {'x': float(centre[0]), 'y': float(centre[1]),
                                    'z': float(centre[2])},
                       'backgroundColor': 'black', 'backgroundOpacity': 0.7,
                       'fontColor': 'white', 'fontSize': 12,
                       'inFront': True})

        n_short = 0
        for el, pos, dist in shell:
            short = (expected_distance is not None
                     and dist < 0.85 * expected_distance)
            n_short += short
            view.addSphere({'center': {'x': float(pos[0]), 'y': float(pos[1]),
                                       'z': float(pos[2])},
                            'radius': 0.40,
                            'color': VIZ_ELEMENT_COLOURS.get(el, VIZ_DEFAULT_COLOUR)})
            view.addCylinder({'start': {'x': float(centre[0]), 'y': float(centre[1]),
                                        'z': float(centre[2])},
                              'end': {'x': float(pos[0]), 'y': float(pos[1]),
                                      'z': float(pos[2])},
                              'radius': 0.10,
                              'color': '#e41a1c' if short else '#666666'})
            mid = (centre + pos) / 2.0
            view.addLabel(f"{dist:.3f}",
                          {'position': {'x': float(mid[0]), 'y': float(mid[1]),
                                        'z': float(mid[2])},
                           'backgroundColor': '#e41a1c' if short else 'white',
                           'backgroundOpacity': 0.85,
                           'fontColor': 'white' if short else 'black',
                           'fontSize': 10, 'inFront': True})

        # context: the next neighbours out, no bonds, no labels
        for el, pos, dist in outer:
            view.addSphere({'center': {'x': float(pos[0]), 'y': float(pos[1]),
                                       'z': float(pos[2])},
                            'radius': 0.22, 'opacity': 0.30,
                            'color': VIZ_ELEMENT_COLOURS.get(el, VIZ_DEFAULT_COLOUR)})

        view.zoomTo()
        view.zoom(0.85)

        print(f"  Coordination shell: {len(shell)} ligands"
              + (f", {n_short} shorter than 85% of the expected "
                 f"{expected_distance:.2f} A" if n_short else ""))
        for el, _pos, dist in shell:
            flag = "  <-- implausibly short" if (
                expected_distance and dist < 0.85 * expected_distance) else ""
            print(f"    {element}-{el}  {dist:.4f} A{flag}")
        if outer:
            gap = outer[0][2] - shell[-1][2]
            print(f"  Next neighbours begin at {outer[0][2]:.4f} A, "
                  f"a gap of {gap:.4f} A (drawn faint, no bonds)")

        display(view)
        print()

    except Exception as e:
        print(f"  [3D visualisation failed: {e}]")


# Radii used only for colouring the picture, not for any calculation
SHANNON_CN6_VIZ = {
    'Li': 0.76, 'Na': 1.02, 'K': 1.38, 'Mg': 0.72, 'Ca': 1.00, 'Al': 0.535,
    'Sc': 0.745, 'Ti': 0.605, 'V': 0.58, 'Cr': 0.615, 'Mn': 0.645,
    'Fe': 0.645, 'Co': 0.61, 'Ni': 0.60, 'Cu': 0.73, 'Zn': 0.74,
    'Sb': 0.60, 'Nb': 0.64, 'Ru': 0.62, 'Sr': 1.18, 'Ba': 1.35,
    'O': 1.40, 'F': 1.33, 'Cl': 1.81, 'S': 1.84, 'N': 1.46,
}


# ============================================================================
# JAHN-TELLER ION DETECTION
# ============================================================================

# ============================================================================
# JAHN-TELLER OCTAHEDRAL CATIONS (element-gated)
# ============================================================================
# Strong (e_g-degenerate) octahedral JT cations form 4+2 elongated octahedra:
#   d4 HS (Cr2+, Mn3+, Fe4+), d7 LS (Ni3+), d9 (Cu2+, Ag2+).
# The gap analysis in auto_analyze_coordination (Cell 4) cuts at the largest
# bond gap, which for these ions is the equatorial->axial gap, wrongly
# returning CN=4. The fix there restores the axial pair, gated on ELEMENT
# only: at that point in Cell 4 the valence is not yet assigned, so central_type
# is all we have. Safety comes from geometry, not oxidation state — the fix only
# fires on a genuine 4+2 within MAX_JT_AXIAL_RATIO, so non-JT members of this
# set (Cr3+, Fe3+) are never touched: a clean octahedron is already CN=6 and a
# real tetrahedron's axials sit far beyond the ratio.
JT_OCTAHEDRAL_ELEMENTS = {'Cr', 'Mn', 'Fe', 'Ni', 'Cu', 'Ag'}
MAX_JT_AXIAL_RATIO = 1.30  # axial/equatorial-mean ceiling for a bonding axial

# Ions whose ground-state d-electron count gives a degenerate e_g or t_2g
# occupation and therefore a first-order Jahn-Teller distortion. High-spin d4
# and d9 are the strong cases; low-spin d7 is included because Ni(III) and
# Co(II) in octahedral oxide environments do distort. Weak (t_2g) cases are
# deliberately excluded: their distortions are far too small to widen a
# coordination-shell gap.
JAHN_TELLER_IONS = {
    ('Cr', 2), ('Mn', 3), ('Fe', 4),            # high-spin d4
    ('Cu', 2), ('Ag', 2), ('Ni', 1),            # d9
    ('Ni', 3), ('Co', 2), ('Rh', 2), ('Pd', 3), # low-spin d7
    ('Mn', 6), ('Cr', 4),                       # d2 tetrahedral, occasionally
}


def is_jahn_teller_ion(element, valence):
    """
    Whether an ion is expected to show a first-order Jahn-Teller distortion.

    v1.8.4: this was called by detect_coordination_adaptive() but had never
    been defined anywhere, so any call raised NameError. The function was
    unreachable in practice, which is why it was never noticed.

    Fractional valences are rounded to the nearest integer, since a
    site-averaged valence of 3.3 on manganese still contains Mn(III).
    """
    if element is None or valence is None:
        return False
    try:
        v = int(round(float(valence)))
    except (TypeError, ValueError):
        return False
    return (element, v) in JAHN_TELLER_IONS

# ============================================================================
# ADAPTIVE GAP DETECTION FOR COORDINATION
# ============================================================================

def detect_coordination_adaptive(bond_distances, element=None, valence=None, min_gap=0.05):
    """Adaptive coordination number detection with special handling for Jahn-Teller ions."""
    if len(bond_distances) < 2:
        return len(bond_distances)
    
    is_jt = False
    if element and valence:
        is_jt = is_jahn_teller_ion(element, valence)
    
    effective_min_gap = min_gap * 2.0 if is_jt else min_gap
    
    gaps = []
    for i in range(len(bond_distances) - 1):
        gap = bond_distances[i+1] - bond_distances[i]
        if gap >= effective_min_gap:
            gaps.append((gap, i+1))
    
    if not gaps:
        return sum(1 for d in bond_distances if d <= 1.30 * bond_distances[0])
    
    largest_gap, cn = max(gaps, key=lambda x: x[0])
    return cn


# ============================================================================
# ICSD METADATA EXTRACTION WITH TEMPERATURE & PRESSURE
# ============================================================================

def extract_icsd_metadata(cif_path):
    """
    Extract publication metadata AND measurement conditions from ICSD CIF file.
    """
    metadata = {
        'icsd_code': None,
        'creation_date': None,
        'year': None,
        'journal': None,
        'authors': [],
        'r_factor': None,
        'density': None,
        'measurement_temperature_K': None,
        'measurement_pressure_Pa': None,
        'measurement_pressure_GPa': None,
        'measurement_conditions': 'unknown'
    }
    
    try:
        with open(cif_path, 'r', encoding='utf-8', errors='ignore') as f:
            lines = f.readlines()
        
        in_citation_loop = False
        in_author_loop = False
        citation_columns = []
        author_columns = []
        
        for i, line in enumerate(lines):
            line_stripped = line.strip()
            
            if line_stripped.startswith('_database_code_ICSD'):
                parts = line_stripped.split()
                if len(parts) > 1:
                    metadata['icsd_code'] = parts[1]
            
            elif line_stripped.startswith('_audit_creation_date'):
                parts = line_stripped.split()
                if len(parts) > 1:
                    metadata['creation_date'] = parts[1]
            
            elif line_stripped.startswith('_exptl_crystal_density_diffrn'):
                parts = line_stripped.split()
                if len(parts) > 1:
                    try:
                        metadata['density'] = float(parts[1])
                    except ValueError:
                        pass
            
            elif line_stripped.startswith('_diffrn_ambient_temperature'):
                parts = line_stripped.split()
                if len(parts) > 1:
                    try:
                        temp_str = parts[1].split('(')[0].strip()
                        metadata['measurement_temperature_K'] = float(temp_str)
                    except ValueError:
                        pass
            
            elif line_stripped.startswith('_cell_measurement_temperature'):
                parts = line_stripped.split()
                if len(parts) > 1 and metadata['measurement_temperature_K'] is None:
                    try:
                        temp_str = parts[1].split('(')[0].strip()
                        metadata['measurement_temperature_K'] = float(temp_str)
                    except ValueError:
                        pass
            
            elif line_stripped.startswith('_diffrn_ambient_pressure'):
                parts = line_stripped.split()
                if len(parts) > 1:
                    try:
                        pressure_str = parts[1].split('(')[0].strip()
                        pressure_kpa = float(pressure_str)
                        metadata['measurement_pressure_Pa'] = pressure_kpa * 1000
                        metadata['measurement_pressure_GPa'] = pressure_kpa / 1e6
                    except ValueError:
                        pass
            
            elif any(tag in line_stripped for tag in ['_refine_ls_R_factor', '_refine_ls_wR_factor']):
                parts = line_stripped.split()
                if len(parts) > 1:
                    try:
                        r_val = float(parts[1])
                        if metadata['r_factor'] is None or r_val < metadata['r_factor']:
                            metadata['r_factor'] = r_val
                    except ValueError:
                        pass
            
            elif line_stripped.startswith('loop_'):
                in_citation_loop = False
                in_author_loop = False
                citation_columns = []
                author_columns = []
            
            elif line_stripped.startswith('_citation_') and not line_stripped.startswith('_citation_author'):
                in_citation_loop = True
                citation_columns.append(line_stripped)
            
            elif line_stripped.startswith('_citation_author'):
                in_author_loop = True
                in_citation_loop = False
                author_columns.append(line_stripped)
            
            elif in_citation_loop and citation_columns and not line_stripped.startswith('_') and not line_stripped.startswith('#') and line_stripped:
                # Robust extraction handling semicolon-delimited multiline fields
                # (common in ICSD CIFs for long journal names).
                # Collects all field values for the primary citation row,
                # then looks up year and journal by column index.
                import shlex as _shlex
                fields = []
                in_semi = False
                semi_buf = []
                j = i

                while j < len(lines):
                    jline = lines[j].strip()
                    # Stop at next loop_ or column definition (but only after
                    # we've started collecting, to avoid stopping immediately)
                    if j > i and (jline.startswith('loop_') or
                                  (jline.startswith('_') and fields)):
                        break
                    if jline.startswith(';'):
                        if in_semi:
                            fields.append(' '.join(semi_buf))
                            semi_buf = []
                            in_semi = False
                            rest = jline[1:].strip()
                            if rest:
                                try:
                                    fields.extend(_shlex.split(rest))
                                except ValueError:
                                    pass
                        else:
                            in_semi = True
                            after = jline[1:].strip()
                            if after:
                                semi_buf.append(after)
                    elif in_semi:
                        semi_buf.append(jline)
                    elif jline:
                        try:
                            fields.extend(_shlex.split(jline))
                        except ValueError:
                            pass
                    j += 1

                if fields and fields[0] == 'primary':
                    for col_idx, col_name in enumerate(citation_columns):
                        if col_idx < len(fields):
                            if '_citation_year' in col_name:
                                try:
                                    metadata['year'] = int(fields[col_idx])
                                except ValueError:
                                    pass
                            elif '_citation_journal_full' in col_name:
                                metadata['journal'] = fields[col_idx]

                in_citation_loop = False
            
            elif in_author_loop and author_columns and not line_stripped.startswith('_') and not line_stripped.startswith('#') and not line_stripped.startswith('loop_') and line_stripped:
                import shlex
                try:
                    values = shlex.split(line_stripped)
                    for col_idx, col_name in enumerate(author_columns):
                        if '_citation_author_name' in col_name and col_idx < len(values):
                            author = values[col_idx]
                            if author and author not in metadata['authors']:
                                metadata['authors'].append(author)
                except ValueError:
                    pass
            
            elif in_author_loop and (line_stripped.startswith('_') or line_stripped.startswith('loop_')):
                in_author_loop = False
        
        if len(metadata['authors']) > 3:
            metadata['authors'] = metadata['authors'][:3] + ['et al.']
        
        # Classify measurement conditions
        temp_K = metadata['measurement_temperature_K']
        pressure_GPa = metadata['measurement_pressure_GPa']
        
        TEMP_AMBIENT_MAX = 350
        TEMP_HIGH = 500
        PRESSURE_AMBIENT_MAX = 0.0002
        PRESSURE_HIGH = 0.5
        
        if temp_K is not None or pressure_GPa is not None:
            is_high_temp = False
            is_high_pressure = False
            is_ambient_temp = True
            is_ambient_pressure = True
            
            if temp_K is not None:
                if temp_K > TEMP_HIGH:
                    is_high_temp = True
                    is_ambient_temp = False
                elif temp_K > TEMP_AMBIENT_MAX:
                    is_ambient_temp = False
            
            if pressure_GPa is not None:
                if pressure_GPa > PRESSURE_HIGH:
                    is_high_pressure = True
                    is_ambient_pressure = False
                elif pressure_GPa > PRESSURE_AMBIENT_MAX:
                    is_ambient_pressure = False
            
            if is_high_temp and is_high_pressure:
                metadata['measurement_conditions'] = 'high_T_high_P'
            elif is_high_temp:
                metadata['measurement_conditions'] = 'high_T'
            elif is_high_pressure:
                metadata['measurement_conditions'] = 'high_P'
            elif is_ambient_temp and is_ambient_pressure:
                metadata['measurement_conditions'] = 'ambient'
            else:
                metadata['measurement_conditions'] = 'elevated'
        else:
            metadata['measurement_conditions'] = 'unknown'
        
    except Exception as e:
        print(f"  [Warning: Could not extract all metadata: {e}]")
    
    return metadata


